      '</div>';
    ['#universalBatchWorkspace', '#batchRawWorkspace'].forEach(function(sel){
      var n = legacy.querySelector(sel);
      if(n) batch.appendChild(n);
    });

    // Fase 1A: id stabil per kalkulator (slug dari judul bersih; slug kembar diberi -2)
    var slugSeen = {};
    function slugId(title){
      var base = slugify(title) || 'kalkulator';
      var id = base, run = 1;
      while (slugSeen[id]) { run++; id = base + '-' + run; }
      slugSeen[id] = true;
      return id;
    }
    // Classify all sections
    var sections = [].slice.call(legacy.querySelectorAll('.section'));
    var groupLabels = [].slice.call(legacy.querySelectorAll('.group-label'));
    var currentGroup = 'Konversi & Referensi';
    [].slice.call(legacy.children).forEach(function(n){
      if(n.classList && n.classList.contains('group-label')) currentGroup = mapCategory(n.textContent);
      if(n.classList && n.classList.contains('section')){
        n.dataset.soilsCategory = currentGroup;
        n.dataset.soilsTitle = clean((n.querySelector('h2')||{}).textContent);
        n.dataset.soilsFormula = ((n.querySelector('.formula')||{}).textContent || '').trim();
        n.dataset.soilsKeywords = clean(n.textContent);
        n.dataset.soilsId = slugId(n.dataset.soilsTitle);
        n.style.display = 'none'; // Initially hidden
      }
    });

