/* Extracted from <script> */
window.SOILS_UBATCH2=(function(){
  'use strict';
  let defs=[],last=[];
  const META={
    hitungKB:{label:'Kejenuhan Basa (KB)',formula:'KB = (Ca + Mg + K + Na) / KTK × 100',unit:'%',inputs:[
      {id:'ca-kb-batch',label:'Ca-tukar (me/100g)',type:'number',required:true},
      {id:'mg-kb-batch',label:'Mg-tukar (me/100g)',type:'number',required:true},
      {id:'k-kb-batch',label:'K-tukar (me/100g)',type:'number',required:true},
      {id:'na-kb-batch',label:'Na-tukar (me/100g)',type:'number',required:true},
      {id:'ktk-kb-batch',label:'KTK (me/100g)',type:'number',required:true}],
      compute:function(v){const n=x=>Number(String(x??'').trim().replace(/\s/g,'').replace(',','.'));const a=v.map(n);if(a.some(x=>!Number.isFinite(x))||a[4]<=0)return NaN;return (a[0]+a[1]+a[2]+a[3])/a[4]*100;},display:function(x){return x.toFixed(2)+' %';}
    }
  };
  function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
  function numText(x){return String(x??'').trim().replace(/\s/g,'').replace(/,/g,'.');}
  function titleNumber(title){const match=String(title||'').match(/^\s*(\d+)\s*\./);return match?Number(match[1]):Number.MAX_SAFE_INTEGER;}
  function numericTitleOrder(a,b){const delta=titleNumber(a.d.title)-titleNumber(b.d.title);return delta||String(a.d.title).localeCompare(String(b.d.title),'id');}
  function idRefs(source){return [...new Set((source.match(/getElementById\(\s*["']([^"']+)["']\s*\)/g)||[]).map(x=>{const m=x.match(/["']([^"']+)["']/);return m&&m[1];}).filter(Boolean))];}
  function discover(){
    const out=[],seen=new Set();
    document.querySelectorAll('.section').forEach(sec=>{
      const h=sec.querySelector('h2'); if(!h)return;
      const btn=[...sec.querySelectorAll('button[onclick]')].find(b=>/hitung[A-Za-z0-9_]+\s*\(/.test(b.getAttribute('onclick')||''));
      if(!btn)return; const m=(btn.getAttribute('onclick')||'').match(/(?:^|;|\s)(hitung[A-Za-z0-9_]+)\s*\(/); if(!m||seen.has(m[1]))return;
      const fnName=m[1],fn=window[fnName]; if(typeof fn!=='function')return; seen.add(fnName);
      const source=fn.toString(), refs=idRefs(source);
      const all=[...sec.querySelectorAll('input[id],select[id],textarea[id]')].filter(el=>!['button','submit'].includes(el.type));
      let inputs=all.filter(el=>refs.includes(el.id));
      if(!inputs.length)inputs=all;
      // Inputs referenced by the function are the batch variables. Exclude obvious output/error containers.
      inputs=inputs.filter(el=>!/(^err-|^hasil-|narasi|-(val|out)$)/i.test(el.id));
      const inputIds=new Set(inputs.map(x=>x.id));
      const outputIds=refs.filter(id=>!inputIds.has(id)&&/(val|out|narasi|hasil|result|output)/i.test(id));
      const errorIds=refs.filter(id=>/^err-|error/i.test(id));
      const requiredIds=new Set(inputs.filter(el=>inferRequired(source,el)).map(el=>el.id));
      const group=(h.textContent||'').replace(/\s+/g,' ').trim();
      out.push({fn:fnName,title:group,sec,inputs,outputIds,errorIds,requiredIds,source});
    });
    return out;
  }
  function inferRequired(source,el){
    const id=el.id.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    if(new RegExp(id+'[^;\\n]{0,220}(?:\\|\\||\\?\\?)').test(source))return false;
    return true;
  }
  function labelFor(el){
    const by=el.id&&document.querySelector('label[for="'+CSS.escape(el.id)+'"]'); if(by)return by.textContent.replace(/\s+/g,' ').trim();
    const p=el.parentElement;const l=p&&p.querySelector('label');if(l)return l.textContent.replace(/\s+/g,' ').trim();
    return el.id||'Input';
  }
  function fields(d){return META[d.fn]?META[d.fn].inputs:d.inputs.map(el=>({id:el.id,label:labelFor(el),type:el.type||'text',required:d.requiredIds.has(el.id),sourceEl:el}));}
  function current(){return defs[Number(document.getElementById('ub2Method').value)||0];}
  function scoreMatch(d,q){
    if(!q)return 0;
    const title=(d.title||'').toLowerCase(), fn=(d.fn||'').toLowerCase(), labels=d.inputs.map(x=>labelFor(x)).join(' ').toLowerCase();
    const hay=title+' '+fn+' '+labels;
    let score=0;
    if(title===q)score+=100; if(title.includes(q))score+=50; if(fn.includes(q))score+=30;
    q.split(/\s+/).filter(Boolean).forEach(t=>{if(title.includes(t))score+=18;if(labels.includes(t))score+=10;if(fn.includes(t))score+=8;});
    return score;
  }
  function renderRecommendations(search,filtered){
    const box=document.getElementById('ub2Recommendations'); if(!box)return;
    const q=(search||'').trim().toLowerCase();
    const source=defs.map((d,i)=>({d,i,score:scoreMatch(d,q)})).filter(x=>q?x.score>0:true).sort((a,b)=>b.score-a.score||numericTitleOrder(a,b)).slice(0,6);
    if(!q){box.innerHTML='<div class="ub2-note">💡 <b>Rekomendasi cepat:</b> ketik nama/parameter di kotak pencarian untuk mendapatkan kalkulator yang paling mendekati.</div>';return;}
    if(!source.length){box.innerHTML='<div class="ub2-info">🔎 Belum menemukan yang cocok. Coba kata seperti <b>KB</b>, <b>KTK</b>, <b>C-organik</b>, <b>N-total</b>, <b>pH</b>, <b>tekstur</b>, <b>air</b>, atau <b>pupuk</b>.</div>';return;}
    box.innerHTML='<div style="font-size:12px;font-weight:700;margin-bottom:6px">🎯 Rekomendasi terdekat</div><div style="display:flex;flex-wrap:wrap;gap:6px">'+source.map(x=>'<button type="button" class="ub2-secondary" data-ub2-rec="'+x.i+'" style="font-size:12px;padding:7px 10px">'+esc(x.d.title)+'</button>').join('')+'</div><div class="ub2-note">Klik rekomendasi untuk memilihnya. Daftar utama di bawah juga sudah difilter.</div>';
    box.querySelectorAll('[data-ub2-rec]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('ub2Method').value=b.getAttribute('data-ub2-rec');build();}));
  }
  function renderMethodOptions(){
    const sel=document.getElementById('ub2Method');
    if(!sel) return;
    const status=document.getElementById('ub2Status');
    const wrap=document.getElementById('ub2TableWrap');
    const summary=document.getElementById('ub2Summary');
    const search=(document.getElementById('ub2Search')?.value||'').trim().toLowerCase();
    const oldFn=current()?.fn;
    const ranked=defs.map(d=>({d,score:scoreMatch(d,search)}));
    const filtered=ranked.filter(x=>!search||x.score>0).sort((a,b)=>search?(b.score-a.score||numericTitleOrder(a,b)):numericTitleOrder(a,b));
    sel.innerHTML=filtered.map(x=>'<option value="'+defs.indexOf(x.d)+'">'+esc(x.d.title)+'</option>').join('');
    if(!filtered.length){
      sel.innerHTML='<option value="">Tidak ada kalkulator yang cocok</option>';
      if(status) status.textContent='0 hasil pencarian';
      if(wrap) wrap.innerHTML='';
      if(summary) summary.innerHTML='';
      return;
    }
    const keep=filtered.find(x=>x.d.fn===oldFn);
    sel.value=String(defs.indexOf(keep?keep.d:filtered[0].d));
    if(status) status.textContent=(search?filtered.length+' hasil':'Semua '+filtered.length)+' kalkulator';
    build();
  }

  function init(){
    defs=discover();
    const sel=document.getElementById('ub2Method');
    const search=document.getElementById('ub2Search');
    if(sel) sel.addEventListener('change',build);
    if(search) search.addEventListener('input',renderMethodOptions);
    renderMethodOptions();
  }
  function build(){
    const d=current();if(!d)return;const fs=fields(d),n=Math.max(0,Number(document.getElementById('ub2Count').value)||4);
    let h='<table style="width:100%; border-collapse:collapse;"><thead><tr><th>Sampel</th>'+fs.map(f=>'<th>'+esc(f.label)+'</th>').join('')+'<th>Hasil</th><th></th></tr></thead><tbody>';
    for(let r=0;r<n;r++){
      h+='<tr data-row="'+r+'"><td><input data-ub2="sample" data-row="'+r+'" value="S'+(r+1)+'" style="width:80px;padding:8px;"></td>';
      fs.forEach((f,i)=>{h+='<td><input data-ub2="'+i+'" data-row="'+r+'" style="width:100px;padding:8px;"></td>';});
      h+='<td class="ub2-result" id="ub2out'+r+'" style="padding:8px;">—</td>';
      h+='<td style="padding:8px;"><button type="button" onclick="SOILS_UBATCH2.removeRow('+r+')" style="color:#d92d20;border:none;background:transparent;cursor:pointer;">✕</button></td></tr>';
    }
    h+='</tbody></table>';
    document.getElementById('ub2TableWrap').innerHTML=h;
    document.getElementById('ub2Status').textContent=n+' sampel siap';
  }
  function addRow(){document.getElementById('ub2Count').value=Number(document.getElementById('ub2Count').value||0)+1;build();}
  function removeRow(r){
    const n=Number(document.getElementById('ub2Count').value||0);
    if(n<=1) return;
    const inputs=document.querySelectorAll('#ub2TableWrap input');
    const rowData=[];
    for(let i=0;i<n;i++){
      if(i===r) continue;
      const rData={};
      document.querySelectorAll('[data-row="'+i+'"]').forEach(el=>{rData[el.getAttribute('data-ub2')]=el.value;});
      rowData.push(rData);
    }
    document.getElementById('ub2Count').value=n-1;
    build();
    rowData.forEach((data,i)=>{
      Object.keys(data).forEach(key=>{
        const el=document.querySelector('[data-ub2="'+key+'"][data-row="'+i+'"]');
        if(el) el.value=data[key];
      });
    });
  }
  function snapshot(sec){
    const nodes=[...sec.querySelectorAll('*')];const snap=new Map();nodes.forEach(el=>{if(el.id||el.classList.contains('result'))snap.set(el,{text:el.textContent,display:el.style.display,value:('value'in el)?el.value:null,checked:('checked'in el)?el.checked:null});});return snap;
  }
  function restore(snap){snap.forEach((v,el)=>{el.textContent=v.text;el.style.display=v.display;if(v.value!==null)el.value=v.value;if(v.checked!==null)el.checked=v.checked;});}
  function setValue(el,v){
    const s=String(v??'').trim(); if(el.tagName==='SELECT'){const opt=[...el.options].find(o=>o.value===s)||[...el.options].find(o=>o.textContent.trim().toLowerCase()===s.toLowerCase());if(opt)el.value=opt.value;else el.value=s;}else if(el.type==='checkbox'||el.type==='radio')el.checked=/^(true|1|yes|ya|on)$/i.test(s);else el.value=s;
  }
  function outputText(d,metaBefore){
    if(metaBefore){const parts=[];const seen=new Set();d.outputIds.forEach(id=>{const el=document.getElementById(id);if(el&&el.textContent.trim()&&el.textContent.trim()!==metaBefore.get(el)?.text){const t=el.textContent.replace(/\s+/g,' ').trim();if(t&&!seen.has(t)){seen.add(t);parts.push(t);}}});return parts.join(' | ');}
    const result=d.sec.querySelector('.result');return result?result.textContent.replace(/\s+/g,' ').trim():'';
  }

  function calculate(){
    const d=current();if(!d)return;const fs=fields(d),n=Number(document.getElementById('ub2Count').value)||0;last=[];let ok=0;
    let invalid=0, missing=0;
    if(META[d.fn]){
      const meta=META[d.fn];for(let r=0;r<n;r++){
        const sample=document.querySelector('[data-ub2="sample"][data-row="'+r+'"]')?.value||('S'+(r+1));
        const vals=fs.map((_,i)=>document.querySelector('[data-ub2="'+i+'"][data-row="'+r+'"]')?.value||'');
        if(vals.every(v=>!String(v).trim())){
          missing++;
          const out=document.getElementById('ub2out'+r);out.textContent='Lengkapi data';out.className='ub2-result ub2-missing';
          last.push({sample,...Object.fromEntries(fs.map((f,i)=>[f.id,vals[i]])),hasil:'',status:'MISSING'});
          continue;
        }
        const x=meta.compute(vals),valid=Number.isFinite(x);
        if(valid) ok++; else invalid++;
        const out=document.getElementById('ub2out'+r);
        out.innerHTML=valid?'<span class="ub2-output">'+esc(meta.display?meta.display(x):String(x))+'</span>':'<span style="color:#b42318">⚠ Input tidak valid</span>';
        out.className='ub2-result '+(valid?'ub2-ok':'ub2-err');
        last.push({sample,...Object.fromEntries(fs.map((f,i)=>[f.id,vals[i]])),hasil:valid?x:'',satuan:meta.unit||'',status:valid?'OK':'INVALID'});
      }
    }else{
      const saved=fs.map(f=>({el:d.inputs.find(x=>x.id===f.id),value:(d.inputs.find(x=>x.id===f.id)||{}).value,checked:(d.inputs.find(x=>x.id===f.id)||{}).checked}));
      for(let r=0;r<n;r++){
        const sample=document.querySelector('[data-ub2="sample"][data-row="'+r+'"]')?.value||('S'+(r+1));
        const vals=fs.map((_,i)=>document.querySelector('[data-ub2="'+i+'"][data-row="'+r+'"]')?.value||'');
        if(vals.every(v=>!String(v).trim())){
          missing++;
          const out=document.getElementById('ub2out'+r);out.textContent='Lengkapi data';out.className='ub2-result ub2-missing';
          last.push({sample,...Object.fromEntries(fs.map((f,i)=>[f.id,vals[i]])),hasil:'',status:'MISSING'});
          continue;
        }
        const snap=snapshot(d.sec);let err='';
        try{fs.forEach((f,i)=>{const el=d.inputs.find(x=>x.id===f.id);if(el)setValue(el,vals[i]);});window[d.fn]();}catch(e){err=e?.message||String(e)}
        const result=outputText(d,snap);const errTexts=d.errorIds.map(id=>document.getElementById(id)?.textContent?.trim()).filter(Boolean);const errText=errTexts.join(' | ');const bad=!!err||/error|harus|wajib|tidak valid|isi dulu|masukkan|⚠/i.test(errText)||!result;
        if(!bad) ok++; else invalid++;
        const out=document.getElementById('ub2out'+r);
        if(bad){
          out.textContent = err?'⚠ '+err:(errText?'⚠ '+errText:'⚠ Tidak ada hasil yang terdeteksi');
        } else {
          var items = result.split(/\s*\|\s*/).filter(Boolean);
          if(items.length > 1){
            out.innerHTML = '<div class="ub2-result-wrap">' + items.map(function(it){ return '<span class="ub2-result-item">'+esc(it)+'</span>'; }).join('') + '</div>';
          } else {
            out.textContent = result;
          }
        }
        out.className='ub2-result '+(bad?'ub2-err':'ub2-ok');last.push({sample,...Object.fromEntries(fs.map((f,i)=>[f.id,vals[i]])),hasil:result,error:err||errText,status:bad?'INVALID':'OK'});restore(snap);
      }
      saved.forEach(x=>{if(x.el){x.el.value=x.value;if(x.el.checked!==undefined&&x.checked!==null)x.el.checked=x.checked;}});
    }
    let statusText = '';
    if(ok === n) {
      statusText = n + ' sampel dihitung.';
    } else {
      const parts = [];
      if(ok > 0) parts.push(ok + ' dihitung');
      if(missing > 0) parts.push(missing + ' belum lengkap');
      if(invalid > 0) parts.push(invalid + ' perlu diperiksa');
      statusText = parts.join(', ') + '.';
    }
    const stEl = document.getElementById('ub2Status');
    if(stEl) stEl.textContent = statusText;
  }
  function openPaste(){document.getElementById('ub2PasteBox').style.display='block';document.getElementById('ub2PasteInput').focus()}
  function closePaste(){document.getElementById('ub2PasteBox').style.display='none'}
  function importFile(input){
    const file = input.files[0];
    if(!file) return;
    const name = file.name.toLowerCase();
    if(name.endsWith('.xlsx') || name.endsWith('.xls') || name.endsWith('.ods')){
      if(typeof XLSX === 'undefined'){
        const hint = document.getElementById('ub2PasteHint');
        if(hint) hint.textContent = '⚠ Library SheetJS (XLSX) belum dimuat.';
        return;
      }
      const reader = new FileReader();
      reader.onload = function(e){
        try {
          const data = new Uint8Array(e.target.result);
          const workbook = XLSX.read(data, {type: 'array'});
          const firstSheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[firstSheetName];
          const csv = XLSX.utils.sheet_to_csv(worksheet, {FS: '\t'});
          document.getElementById('ub2PasteInput').value = csv;
          openPaste();
          importPaste();
          input.value = '';
          const hint = document.getElementById('ub2PasteHint');
          if(hint) hint.textContent = '✅ Berhasil memparsing file Excel (.xlsx/.xls) via SheetJS.';
        } catch(err) {
          const hint = document.getElementById('ub2PasteHint');
          if(hint) hint.textContent = '⚠ Gagal membaca file Excel: ' + err.message;
        }
      };
      reader.readAsArrayBuffer(file);
    } else {
      const reader = new FileReader();
      reader.onload = function(e){
        document.getElementById('ub2PasteInput').value = e.target.result;
        openPaste();
        importPaste();
        input.value = '';
        const hint = document.getElementById('ub2PasteHint');
        if(hint) hint.textContent = '✅ Berhasil memuat file teks/CSV.';
      };
      reader.readAsText(file);
    }
  }
  function importPaste(){
    const t=document.getElementById('ub2PasteInput').value.trim();if(!t){const hint=document.getElementById('ub2PasteHint');if(hint)hint.textContent='⚠ Belum ada data.';return}
    const d=current(),fs=fields(d),expected=fs.length+1;
    let rows=t.split(/\r?\n/).filter(x=>x.trim()).map(line => {
      if(line.includes('\t')) return line.split('\t');
      if(line.includes(';')) return line.split(';');
      return line.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/);
    });
    const first=rows[0].map(x=>x.trim().toLowerCase().replace(/^"|"$/g,''));
    const header=first.some(x=>/sampel|sample|ca[- ]?tukar|ktk|c-organik|n-total|pasir|debu|liat/.test(x));
    if(header) rows.shift();
    rows=rows.slice(0,100);
    document.getElementById('ub2Count').value=Math.max(1,rows.length);
    build();
    let bad=0;
    rows.forEach((vals,r)=>{
      const sm=document.querySelector('[data-ub2="sample"][data-row="'+r+'"]');
      if(sm) sm.value=(vals[0]||('S'+(r+1))).trim().replace(/^"|"$/g,'');
      const payload=vals.slice(1).map(x=>x.trim().replace(/^"|"$/g,''));
      if(payload.length!==fs.length) bad++;
      for(let i=0;i<fs.length;i++){
        const x=document.querySelector('[data-ub2="'+i+'"][data-row="'+r+'"]');
        if(x) x.value=numText(payload[i]??'');
      }
    });
    const hint = document.getElementById('ub2PasteHint');
    if(hint) hint.textContent='✅ '+rows.length+' baris masuk · '+(bad?'⚠ '+bad+' baris jumlah kolom berbeda (butuh '+expected+' kolom termasuk Sampel).':'semua kolom sesuai')+' · menghitung...';
    if(!bad) setTimeout(calculate,0);
  }
  function exportCSV(){
    if(!last.length) return;
    const keys=Object.keys(last[0]);
    const csv=keys.join(',')+'\n'+last.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(',')).join('\n');
    const a=document.createElement('a');
    a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
    a.download='SOILS_BATCH_ALL_CALCULATORS.csv';
    a.click();
    setTimeout(()=>URL.revokeObjectURL(a.href),1000);
  }
  function clear(){document.getElementById('ub2TableWrap').innerHTML='';document.getElementById('ub2Summary').innerHTML='';document.getElementById('ub2Meta').innerHTML='';const st=document.getElementById('ub2Status');if(st)st.textContent=defs.length+' kalkulator siap';last=[]}
  document.addEventListener('DOMContentLoaded',init);window.SOILS_UBATCH2={build,calculate,exportCSV,clear,openPaste,closePaste,importPaste,importFile,addRow,removeRow}; return window.SOILS_UBATCH2;
})();


/* Extracted from <script> */
(function(){
function id(x){return document.getElementById(x)}
function num(v){var n=parseFloat(String(v).replace(',','.'));return isFinite(n)?n:null}
function val(ids){for(var i=0;i<ids.length;i++){var e=id(ids[i]);if(e&&e.value!==''){var n=num(e.value);if(n!==null)return n}}return null}
function cls(name,v){
if(name==='pH'){if(v<4.5)return ['Sangat masam','bad'];if(v<5.5)return ['Masam','bad'];if(v<6)return ['Agak masam','warn'];if(v<=7.5)return ['Netral','good'];if(v<=8.5)return ['Agak alkalis','warn'];return ['Alkalis','warn']}
if(name==='C-organik'){if(v<1)return ['Sangat rendah','bad'];if(v<2)return ['Rendah','warn'];if(v<3)return ['Sedang','good'];if(v<5)return ['Tinggi','good'];return ['Sangat tinggi','good']}
if(name==='N-total'){if(v<.1)return ['Sangat rendah','bad'];if(v<.2)return ['Rendah','warn'];if(v<.5)return ['Sedang','good'];if(v<.75)return ['Tinggi','good'];return ['Sangat tinggi','good']}
if(name==='P-tersedia'){if(v<5)return ['Sangat rendah','bad'];if(v<10)return ['Rendah','warn'];if(v<20)return ['Sedang','good'];if(v<40)return ['Tinggi','good'];return ['Sangat tinggi','good']}
if(name==='KTK'){if(v<5)return ['Sangat rendah','bad'];if(v<16)return ['Rendah','warn'];if(v<24)return ['Sedang','good'];if(v<40)return ['Tinggi','good'];return ['Sangat tinggi','good']}
if(name==='BV'){if(v<1.1)return ['Sangat rendah','good'];if(v<1.3)return ['Rendah','good'];if(v<1.5)return ['Sedang','warn'];if(v<1.7)return ['Agak padat','warn'];return ['Padat','bad']}
return ['Terbaca','good']}
window.cleanAutoAnalyze=function(){
var specs=[['pH',['ph']],['C-organik',['corg','corg-cn']],['N-total',['ntotal','ntotal-cn']],['P-tersedia',['pt']],['KTK',['ktk','ktk-kb']],['BV',['kapur-bv','dolomit-bv']]],rows=[],bad=[],warn=[];
specs.forEach(function(s){var v=val(s[1]);if(v===null)return;var c=cls(s[0],v);rows.push([s[0],v,c[0],c[1]]);if(c[1]==='bad')bad.push(s[0]);else if(c[1]==='warn')warn.push(s[0])});
var box=id('auto-result');box.hidden=false;if(!rows.length){box.innerHTML='<div class="auto-summary"><strong>Belum ada parameter yang terbaca.</strong><br>Isi atau jalankan kalkulator yang menggunakan parameter dasar, lalu tekan analisis lagi.</div>';return}
var cards=rows.map(function(r){return '<div class="auto-card '+r[3]+'"><small>'+r[0]+'</small><strong>'+r[1]+'</strong><span>'+r[2]+'</span></div>'}).join('');var overall=bad.length?'Perlu perhatian':warn.length?'Perlu dipantau':'Relatif baik';var detail=bad.concat(warn);
box.innerHTML='<div class="auto-grid">'+cards+'</div><div class="auto-summary"><strong>Kondisi umum: '+overall+'</strong>'+(detail.length?'<br>Parameter yang perlu diperhatikan: '+detail.join(', ')+'.':'<br>Tidak ada parameter yang masuk kategori perhatian berdasarkan aturan ringkas ini.')+'<br><small style="color:#888780">Catatan: kriteria otomatis bersifat bantuan awal dan perlu disesuaikan dengan metode serta acuan praktikum.</small></div>';
};window.cleanAutoClear=function(){var b=id('auto-result');b.hidden=true;b.innerHTML=''};
})();


/* Extracted from <script> */
// ==== Fitur Export Word (per modul) ====
document.addEventListener('DOMContentLoaded', function(){
  document.querySelectorAll('div.result[id]').forEach(function(el){
    var wrap = document.createElement('div');
    wrap.className = 'export-buttons';
    wrap.innerHTML =
      '<button type="button" class="btn-export btn-word" onclick="exportModule(\'' + el.id + '\',\'word\')">📝 Export Word</button>';
    el.appendChild(wrap);
  });
});

var loadedScripts = {};
function loadScriptOnce(src) {
  if (loadedScripts[src]) return loadedScripts[src];
  loadedScripts[src] = new Promise(function(resolve, reject) {
    var s = document.createElement('script');
    s.src = src;
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
  return loadedScripts[src];
}

function exportWordLegacy(title, contentHTML, compactHTML, safeName, waktu, localEscapeHtml) {
  var html = '<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">' +
    '<head><meta charset="utf-8"><meta http-equiv="Content-Type" content="text/html; charset=utf-8"><title>' + localEscapeHtml(title) + '</title></head>' +
    '<body><h2>' + localEscapeHtml(title) + '</h2>' + contentHTML + compactHTML +
    '<p style="margin-top:20px;font-size:9pt;color:#888;">Diekspor dari Kalkulator Interpretasi Data Tanah pada ' + localEscapeHtml(waktu) + '</p></body></html>';
  try {
    var blob = new Blob(['\ufeff', html], {type:'application/msword'});
    var url = URL.createObjectURL(blob);
    var link = document.createElement('a');
    link.href = url;
    link.download = safeName + '.doc';
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    setTimeout(function(){
      try{ link.remove(); }catch(e){}
      try{ URL.revokeObjectURL(url); }catch(e){}
    }, 3000);
  } catch(err) {
    alert('Export Word gagal: ' + (err && err.message ? err.message : err));
  }
}

async function exportModule(resultId, format){
  var resultDiv = document.getElementById(resultId);
  if(!resultDiv){ alert('Hasil kalkulator tidak ditemukan.'); return; }
  var section = resultDiv.closest('.section');
  var h2 = section ? section.querySelector('h2') : null;
  var title = h2 ? h2.textContent.trim() : 'Hasil Kalkulator Tanah';

  function localEscapeHtml(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g,function(c){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  function localCleanText(s){ return String(s == null ? '' : s).replace(/\s+/g,' ').trim(); }

  function localNumberText(v){
    var n=parseFloat(String(v).replace(',','.'));
    return isFinite(n) ? String(n) : String(v);
  }
  function localInputs(sec){
    if(!sec) return [];
    return Array.prototype.slice.call(sec.querySelectorAll('input,select,textarea')).filter(function(el){
      return el.value !== '' && el.id && el.id.indexOf('spa-') !== 0;
    }).map(function(el){
      var wrap=el.closest('div');
      var label=wrap ? wrap.querySelector('label') : null;
      var labelText=localCleanText(label ? label.textContent : '');
      if(!labelText) labelText=el.getAttribute('aria-label') || el.placeholder || el.id;
      return {id:el.id,value:localNumberText(el.value),rawValue:el.value,label:labelText};
    });
  }
  function localAliases(item){
    var a=[], label=localCleanText(item.label), before=localCleanText(label.split('(')[0]), id=item.id||'';
    if(label) a.push(label); if(before && before.length>=2) a.push(before);
    var map={
      'basa':['jumlah basa tukar','basa tukar'],'ktk-kb':['KTK'],
      'corg-cn':['%C-organik','C-organik'],'ntotal-cn':['%N-total','N-total'],
      'aldd':['Al-dd'],'basa-al':['jumlah basa tukar','basa tukar'],
      'kapur-aldd':['Al-dd'],'kapur-bv':['BV'],'kapur-kedalaman':['kedalaman'],
      'kapur-kemurnian':['kemurnian'],'dolomit-aldd':['Al-dd'],'dolomit-bv':['BV'],
      'dolomit-kedalaman':['kedalaman'],'dolomit-kemurnian':['kemurnian'],
      'n-dosis':['Dosis anjuran N'],'n-kadar':['kadar N pupuk'],'n-luas':['luas'],
      'p-dosis':['Dosis anjuran P2O5'],'p-kadar':['kadar P2O5 pupuk'],'p-luas':['luas'],
      'k-dosis':['Dosis anjuran K2O'],'k-kadar':['kadar K2O pupuk'],'k-luas':['luas']
    };
    (map[id]||[]).forEach(function(x){a.push(x);});
    return a.filter(function(x,i,self){return x && self.indexOf(x)===i;}).sort(function(x,y){return y.length-x.length;});
  }
  function localSubstitute(formula,inputs){
    var text=localCleanText(formula); if(!text || !inputs.length) return '';
    inputs.forEach(function(item){
      localAliases(item).some(function(alias){
        var re=new RegExp(alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');
        if(re.test(text)){ text=text.replace(re,localNumberText(item.rawValue)); return true; }
        return false;
      });
    });
    return text.replace(/\s*[xX×]\s*/g,' × ').replace(/\s*\/\s*/g,' / ').replace(/\s*\+\s*/g,' + ').replace(/\s*-\s*/g,' - ').replace(/\s*=\s*/g,' = ');
  }
  function localFirstOutput(resultDiv){
    var card=resultDiv ? resultDiv.querySelector('.result-card') : null;
    if(card){
      var ps=card.querySelectorAll('p');
      if(ps.length>=2) return localCleanText(ps[ps.length-1].textContent);
    }
    return '';
  }

  var clone = resultDiv.cloneNode(true);
  clone.querySelectorAll('.export-buttons,.step-toggle,.stepbox').forEach(function(el){ el.remove(); });

  // Export Word dibuat langsung ke inti perhitungan.
  // Jangan ikutkan kartu "Hasil perhitungan", klasifikasi, atau draf pembahasan.
  // Hasil final tetap ditampilkan pada satu baris Step-by-Step di bawah.
  var contentHTML = clone.innerHTML;

  /* Export hanya menampilkan rumus singkat + substitusi angka aktual. */
  var formulaEl = section ? section.querySelector('.formula') : null;
  var formula = localCleanText(formulaEl ? formulaEl.textContent : '');
  var substitution = '';
  try{
    var inputs = localInputs(section);
    substitution = localSubstitute(formula, inputs);
  }catch(e){ substitution = ''; }

  var stepText = substitution || formula;
  var firstOutput = localFirstOutput(resultDiv);

  /* TEMPLATE WORD: satu baris saja = rumus + angka aktual + hasil akhir.
     Jangan menganggap rumus sudah lengkap hanya karena mengandung "=".
     Contoh: KB = (9 / 10) × 100% = 90%
              C/N = 2 / 0.97 = 2.1
  */
  if(stepText && firstOutput){
    var cleanStep = localCleanText(stepText);
    var cleanOut = localCleanText(firstOutput);

    // Tambahkan hasil hanya jika nilai hasil belum menjadi bagian paling akhir.
    var tail = cleanStep.match(/(?:=|≈)\s*([^=]+)$/);
    var alreadyHasResult = tail && localCleanText(tail[1]) === cleanOut;

    if(!alreadyHasResult){
      stepText = cleanStep + ' = ' + cleanOut;
    }else{
      stepText = cleanStep;
    }
  }

  // Export Step by Step mengikuti template yang diberikan:
  // judul singkat + SATU baris perhitungan, tanpa tabel/grup/penjelasan panjang.
  var compactHTML = stepText ?
    '<section class="export-step-section compact-template-word">' +
      '<h2>📘 Cara Pengerjaan</h2>' +
      '<div class="export-formula-line">' + localEscapeHtml(stepText) + '</div>' +
    '</section>' : '';

  var waktu = new Date().toLocaleString('id-ID');
  var safeName = title.replace(/[^a-z0-9]+/gi,'_').replace(/^_+|_+$/g,'').toLowerCase() || 'hasil-kalkulator-tanah';

  if(format === 'word' && resultId === 'hasil-bplot' && window.__bplotLast){
    try {
      await loadScriptOnce('js/vendor/docx.umd.js');
      await loadScriptOnce('js/vendor/filesaver.min.js');
      await loadScriptOnce('js/export-docx.js');

      if (window.docx && window.SoilsDocx && typeof window.SoilsDocx.exportToDocx === 'function') {
        var dataTables = [{
          judul: 'Statistik Data Box Plot',
          header: ['Parameter', 'Nilai'],
          baris: [
            ['Q1', window.__bplotLast.q1],
            ['Median (Q2)', window.__bplotLast.q2],
            ['Q3', window.__bplotLast.q3],
            ['IQR', window.__bplotLast.q3 - window.__bplotLast.q1],
            ['Whisker (Min - Max)', window.SoilsDocx.fmtID(window.__bplotLast.whiskerMin) + ' - ' + window.SoilsDocx.fmtID(window.__bplotLast.whiskerMax)],
            ['Jumlah Outlier', window.__bplotLast.outliers.length]
          ]
        }];
        window.SoilsDocx.exportToDocx(title, dataTables)
          .then(function() { console.log('Ekspor .docx berhasil'); })
          .catch(function(e) {
            console.error('ExportToDocx failed:', e);
            exportWordLegacy(title, contentHTML, compactHTML, safeName, waktu, localEscapeHtml);
          });
        return;
      }
    } catch (e) {
      console.error('Lazy load failed:', e);
    }
    exportWordLegacy(title, contentHTML, compactHTML, safeName, waktu, localEscapeHtml);
    return;
  }

  if(format === 'word'){
    exportWordLegacy(title, contentHTML, compactHTML, safeName, waktu, localEscapeHtml);
    return;
  }

  return;
}

function cap(s){ return s.charAt(0).toUpperCase()+s.slice(1); }

function classifyPh(v){ if(v<4.5) return "sangat masam"; if(v<5.5) return "masam"; if(v<6.5) return "agak masam"; if(v<=7.5) return "netral"; if(v<=8.5) return "agak alkalis"; return "alkalis"; }
function classifyCorg(v){ if(v<1) return "sangat rendah"; if(v<2) return "rendah"; if(v<3) return "sedang"; if(v<5) return "tinggi"; return "sangat tinggi"; }
function classifyNtotal(v){ if(v<0.1) return "sangat rendah"; if(v<0.21) return "rendah"; if(v<0.51) return "sedang"; if(v<0.76) return "tinggi"; return "sangat tinggi"; }
function classifyP(v){ if(v<10) return "sangat rendah"; if(v<16) return "rendah"; if(v<26) return "sedang"; if(v<36) return "tinggi"; return "sangat tinggi"; }
function classifyK(v){ if(v<0.1) return "sangat rendah"; if(v<0.3) return "rendah"; if(v<0.6) return "sedang"; if(v<=1.0) return "tinggi"; return "sangat tinggi"; }
function classifyKtk(v){ if(v<5) return "sangat rendah"; if(v<17) return "rendah"; if(v<25) return "sedang"; if(v<=40) return "tinggi"; return "sangat tinggi"; }
function classifyTrp(v){ if(v<30) return "jelek (terlalu padat)"; if(v<40) return "kurang baik"; if(v<60) return "baik"; if(v<=80) return "sangat baik"; return "kurang baik (terlalu porous)"; }
function classifyPermea(v){ if(v<0.5) return "sangat lambat"; if(v<2.0) return "lambat"; if(v<6.25) return "agak lambat"; if(v<12.5) return "sedang"; if(v<25.0) return "agak cepat"; return "cepat"; }
function classifyKB(v){ if(v<20) return "rendah"; if(v<40) return "sedang"; if(v<60) return "tinggi"; return "sangat tinggi"; }
function classifyCN(v){ if(v<5) return "rendah"; if(v<10) return "sedang"; if(v<15) return "tinggi"; return "sangat tinggi"; }
function classifyDHL(v){ if(v<2) return "tidak salin"; if(v<4) return "agak salin"; if(v<8) return "salin"; if(v<16) return "sangat salin"; return "ekstrem salin"; }
function classifyAl(v){ if(v<10) return "rendah"; if(v<20) return "sedang"; if(v<60) return "tinggi"; return "sangat tinggi"; }
function classifyAT(v){ if(v<10) return "rendah"; if(v<20) return "sedang"; return "tinggi"; }
function classifyCaSaturation(v){ if(v<60) return "rendah"; if(v<=80) return "cukup/optimal"; return "tinggi"; }
function classifyMgSaturation(v){ if(v<10) return "rendah"; if(v<=20) return "cukup/optimal"; return "tinggi"; }
function classifyKSaturation(v){ if(v<2) return "rendah"; if(v<=5) return "cukup/optimal"; return "tinggi"; }
function classifyNaSaturation(v){ if(v<5) return "rendah/normal"; if(v<=15) return "agak tinggi"; return "tinggi (mengarah sodik)"; }
function classifyESP(v){ if(v<15) return "non-sodik (normal)"; return "sodik"; }
function classifySAR(v){ if(v<10) return "rendah"; if(v<18) return "sedang"; if(v<26) return "tinggi"; return "sangat tinggi"; }
function classifyWFPS(v){ if(v<30) return "kering (aerasi tinggi)"; if(v<60) return "optimal untuk aktivitas aerob"; if(v<80) return "lembab, mendekati jenuh"; return "jenuh/tergenang (kondisi anaerob)"; }
function classifyRasioBF(v){ if(v>=3) return "bakteri-dominan"; if(v>=1) return "berimbang (sedikit bakteri-dominan)"; if(v>=0.33) return "berimbang (sedikit jamur-dominan)"; return "jamur-dominan"; }
function classifyShannon(v){ if(v<1.5) return "rendah"; if(v<3.0) return "sedang"; return "tinggi"; }
var statusBioThresholds = {
  bakteri: [1e5,1e6,1e7,1e8],
  jamur: [1e2,1e3,1e4,1e5],
  aktinomicetes: [1e4,1e5,1e6,1e7]
};
function classifyStatusBio(v, kelompok){
  var t = statusBioThresholds[kelompok];
  if(v<t[0]) return "sangat rendah";
  if(v<t[1]) return "rendah";
  if(v<t[2]) return "sedang";
  if(v<t[3]) return "tinggi";
  return "sangat tinggi";
}
var narasiBio = {
  'sangat rendah': "mengindikasikan aktivitas dekomposisi bahan organik dan potensi siklus hara yang sangat terbatas; kondisi ini sering dikaitkan dengan tekanan pengelolaan yang tinggi (penggunaan pestisida/pupuk kimia intensif, minim input bahan organik, atau gangguan fisik tanah)",
  'rendah': "menunjukkan aktivitas dekomposisi dan siklus hara yang masih rendah; perlu dicermati faktor pembatas seperti kadar bahan organik rendah, pH kurang sesuai, atau residu pestisida",
  'sedang': "mengindikasikan aktivitas dekomposisi dan siklus hara yang cukup berjalan, umum dijumpai pada tanah pertanian dengan pengelolaan moderat",
  'tinggi': "menunjukkan aktivitas dekomposisi bahan organik dan siklus hara yang baik, biasanya berkaitan dengan input bahan organik yang cukup dan pengelolaan yang relatif ramah terhadap biota tanah",
  'sangat tinggi': "mengindikasikan aktivitas dekomposisi dan siklus hara yang sangat aktif, umum pada tanah dengan bahan organik tinggi dan minim gangguan (misalnya tanah hutan atau lahan dengan input bahan organik tinggi dan rendah pestisida)"
};

function getTexture(sand, silt, clay){
  if (silt + 1.5*clay < 15) return "Pasir (sand)";
  if (silt + 2*clay < 30) return "Pasir berlempung (loamy sand)";
  if ((clay>=7 && clay<20 && sand>52 && (silt+2*clay)>=30) || (clay<7 && silt<50 && (silt+2*clay)>=30)) return "Lempung berpasir (sandy loam)";
  if (clay>=20 && clay<35 && silt<28 && sand>45) return "Lempung liat berpasir (sandy clay loam)";
  if (clay>=35 && sand>45) return "Liat berpasir (sandy clay)";
  if (clay>=40 && silt>=40) return "Liat berdebu (silty clay)";
  if (clay>=40 && sand<=45 && silt<40) return "Liat (clay)";
  if (clay>=27 && clay<40 && sand>20 && sand<=45) return "Lempung liat (clay loam)";
  if (clay>=27 && clay<40 && sand<=20) return "Lempung liat berdebu (silty clay loam)";
  if (silt>=80 && clay<12) return "Debu (silt)";
  if (silt>=50 && clay>=12 && clay<27) return "Lempung berdebu (silt loam)";
  if (silt>=50 && silt<80 && clay<12) return "Lempung berdebu (silt loam)";
  if (clay>=7 && clay<27 && silt>=28 && silt<50 && sand<=52) return "Lempung (loam)";
  return "Tidak dapat ditentukan, cek kembali persentase";
}

function hitungKimia(){
  var errEl = document.getElementById('err-kimia');
  var ph=parseFloat(document.getElementById('ph').value), corg=parseFloat(document.getElementById('corg').value), ntotal=parseFloat(document.getElementById('ntotal').value);
  var pt=parseFloat(document.getElementById('pt').value), ktukar=parseFloat(document.getElementById('ktukar').value), ktk=parseFloat(document.getElementById('ktk').value);
  var vals=[ph,corg,ntotal,pt,ktukar,ktk];
  if(vals.some(isNaN)){ errEl.textContent='Isi keenam nilai kesuburan.'; errEl.style.display='block'; document.getElementById('hasil-kimia').style.display='none'; return; }
  errEl.style.display='none';
  var phC=classifyPh(ph), corgC=classifyCorg(corg), nC=classifyNtotal(ntotal), pC=classifyP(pt), kC=classifyK(ktukar), ktkC=classifyKtk(ktk);
  document.getElementById('ph-out').textContent=cap(phC);
  document.getElementById('corg-out').textContent=cap(corgC);
  document.getElementById('ntotal-out').textContent=cap(nC);
  document.getElementById('pt-out').textContent=cap(pC);
  document.getElementById('ktukar-out').textContent=cap(kC);
  document.getElementById('ktk-out').textContent=cap(ktkC);
  document.getElementById('narasi-kimia').textContent="Tanah memiliki pH "+ph.toFixed(1)+" ("+phC+"), C-organik "+corg.toFixed(2)+"% ("+corgC+"), N-total "+ntotal.toFixed(2)+"% ("+nC+"), P-tersedia "+pt.toFixed(1)+" ppm ("+pC+"), K-tukar "+ktukar.toFixed(2)+" me/100g ("+kC+"), dan KTK "+ktk.toFixed(1)+" me/100g ("+ktkC+"). Kriteria mengacu pada klasifikasi kesuburan tanah Pusat Penelitian Tanah (Balai Penelitian Tanah, 1983).";
  document.getElementById('hasil-kimia').style.display='block';
}

