function hitungKapur(){
  var errEl=document.getElementById('err-kapur');
  var aldd=parseFloat(document.getElementById('kapur-aldd').value), bv=parseFloat(document.getElementById('kapur-bv').value);
  var kedalaman=parseFloat(document.getElementById('kapur-kedalaman').value), kemurnian=parseFloat(document.getElementById('kapur-kemurnian').value);
  if([aldd,bv,kedalaman,kemurnian].some(isNaN) || aldd<0 || bv<=0 || kedalaman<=0 || kemurnian<=0){ errEl.textContent='Isi Al-dd, BV, kedalaman, dan kemurnian kapur (BV, kedalaman, kemurnian > 0).'; errEl.style.display='block'; document.getElementById('hasil-kapur').style.display='none'; return; }
  errEl.style.display='none';
  var lr=1.5*aldd;
  var caco3=lr*bv*kedalaman*0.05;
  var aktual=caco3/(kemurnian/100);
  document.getElementById('kapur-caco3-val').textContent=caco3.toFixed(2)+' ton/ha';
  document.getElementById('kapur-aktual-val').textContent=aktual.toFixed(2)+' ton/ha';
  document.getElementById('narasi-kapur').textContent="Kebutuhan kapur setara CaCO3 murni sebesar "+caco3.toFixed(2)+" ton/ha (Al-dd "+aldd.toFixed(2)+" me/100g, BV "+bv.toFixed(2)+" g/cm3, kedalaman "+kedalaman.toFixed(0)+" cm). Kebutuhan kapur aktual dengan kemurnian "+kemurnian.toFixed(1)+"% sebesar "+aktual.toFixed(2)+" ton/ha. Rumus mengacu pada metode Al-dd (Kamprath); sesuaikan faktor dengan modul kampus masing-masing.";
  document.getElementById('hasil-kapur').style.display='block';
}

