function hitungPupukNPK(){
  var errEl=document.getElementById('err-pupuknpk');
  var dn=parseFloat(document.getElementById('npk-dosisn').value), dp=parseFloat(document.getElementById('npk-dosisp').value), dk=parseFloat(document.getElementById('npk-dosisk').value);
  var kn=parseFloat(document.getElementById('npk-kadarn').value), kp=parseFloat(document.getElementById('npk-kadarp').value), kk=parseFloat(document.getElementById('npk-kadark').value);
  if([dn,dp,dk,kn,kp,kk].some(isNaN) || kn<=0 || kp<=0 || kk<=0){ errEl.textContent='Isi semua dosis anjuran dan kadar hara NPK (kadar harus > 0).'; errEl.style.display='block'; document.getElementById('hasil-pupuknpk').style.display='none'; return; }
  errEl.style.display='none';
  var needN=dn/(kn/100), needP=dp/(kp/100), needK=dk/(kk/100);
  var rekomendasi=Math.min(needN,needP,needK);
  var pembatas = rekomendasi===needN ? 'N' : (rekomendasi===needP ? 'P2O5' : 'K2O');
  document.getElementById('npk-n-val').textContent=needN.toFixed(1)+' kg/ha';
  document.getElementById('npk-p-val').textContent=needP.toFixed(1)+' kg/ha';
  document.getElementById('npk-k-val').textContent=needK.toFixed(1)+' kg/ha';
  document.getElementById('npk-rekomendasi-val').textContent=rekomendasi.toFixed(1)+' kg/ha';
  document.getElementById('narasi-pupuknpk').textContent="Jika dihitung dari masing-masing unsur, kebutuhan pupuk NPK ("+kn.toFixed(0)+"-"+kp.toFixed(0)+"-"+kk.toFixed(0)+") adalah "+needN.toFixed(1)+" kg/ha (basis N), "+needP.toFixed(1)+" kg/ha (basis P2O5), dan "+needK.toFixed(1)+" kg/ha (basis K2O). Unsur pembatas adalah "+pembatas+", sehingga dosis yang disarankan sebesar "+rekomendasi.toFixed(1)+" kg/ha agar tidak ada unsur yang berlebih; kekurangan dua unsur lainnya pada dosis ini perlu disuplemen dengan pupuk tunggal (Urea/SP-36/KCl).";
  document.getElementById('hasil-pupuknpk').style.display='block';
}

