function hitungSAR(){
  var errEl=document.getElementById('err-sar');
  var na=parseFloat(document.getElementById('sar-na').value), ca=parseFloat(document.getElementById('sar-ca').value), mg=parseFloat(document.getElementById('sar-mg').value);
  if(isNaN(na)||isNaN(ca)||isNaN(mg)||na<0||ca<0||mg<0||(ca+mg)<=0){ errEl.textContent='Isi Na, Ca, dan Mg ekstrak (Ca + Mg harus > 0).'; errEl.style.display='block'; document.getElementById('hasil-sar').style.display='none'; return; }
  errEl.style.display='none';
  var sar=na/Math.sqrt((ca+mg)/2);
  var c=classifySAR(sar);
  document.getElementById('sar-val').textContent=sar.toFixed(2);
  document.getElementById('sar-out').textContent=cap(c);
  document.getElementById('narasi-sar').textContent="Sodium Adsorption Ratio (SAR) pada ekstrak/air irigasi sebesar "+sar.toFixed(2)+" ("+c+" terhadap risiko sodisitas), dari konsentrasi Na "+na.toFixed(2)+" me/L, Ca "+ca.toFixed(2)+" me/L, dan Mg "+mg.toFixed(2)+" me/L. Kategori menurut FAO / U.S. Salinity Laboratory Staff (1954) & Ayers & Westcot (1985).";
  document.getElementById('hasil-sar').style.display='block';
}

var konversiMap = {
  'p-p2o5': {factor:2.2914, from:'P', to:'P2O5'},
  'p2o5-p': {factor:0.4364, from:'P2O5', to:'P'},
  'k-k2o': {factor:1.2046, from:'K', to:'K2O'},
  'k2o-k': {factor:0.8301, from:'K2O', to:'K'},
  'ca-cao': {factor:1.3992, from:'Ca', to:'CaO'},
  'cao-ca': {factor:0.7147, from:'CaO', to:'Ca'},
  'mg-mgo': {factor:1.6579, from:'Mg', to:'MgO'},
  'mgo-mg': {factor:0.6030, from:'MgO', to:'Mg'},
  'n-protein': {factor:6.25, from:'N', to:'Protein kasar'},
  'protein-n': {factor:0.16, from:'Protein kasar', to:'N'}
};

function hitungKonversi(){
  var errEl=document.getElementById('err-konversi');
  var jenis=document.getElementById('konversi-jenis').value;
  var nilai=parseFloat(document.getElementById('konversi-nilai').value);
  if(isNaN(nilai)){ errEl.textContent='Isi nilai yang mau dikonversi.'; errEl.style.display='block'; document.getElementById('hasil-konversi').style.display='none'; return; }
  errEl.style.display='none';
  var m=konversiMap[jenis];
  var hasil=nilai*m.factor;
  document.getElementById('konversi-val').textContent=hasil.toFixed(3)+' ('+m.to+')';
  document.getElementById('narasi-konversi').textContent="Nilai "+nilai+" "+m.from+" setara dengan "+hasil.toFixed(3)+" "+m.to+", menggunakan faktor konversi "+m.factor+" berdasarkan perbandingan berat molekul/ekuivalen standar.";
  document.getElementById('hasil-konversi').style.display='block';
}

var klasifikasiMap = {
  'ph': {fn:classifyPh, satuan:''},
  'corg': {fn:classifyCorg, satuan:'%'},
  'ntotal': {fn:classifyNtotal, satuan:'%'},
  'p': {fn:classifyP, satuan:'ppm'},
  'k': {fn:classifyK, satuan:'me/100g'},
  'ktk': {fn:classifyKtk, satuan:'me/100g'},
  'kb': {fn:classifyKB, satuan:'%'},
  'cn': {fn:classifyCN, satuan:''},
  'al': {fn:classifyAl, satuan:'%'},
  'jca': {fn:classifyCaSaturation, satuan:'%'},
  'jmg': {fn:classifyMgSaturation, satuan:'%'},
  'jk': {fn:classifyKSaturation, satuan:'%'},
  'jna': {fn:classifyNaSaturation, satuan:'%'},
  'esp': {fn:classifyESP, satuan:'%'},
  'sar': {fn:classifySAR, satuan:''},
  'dhl': {fn:classifyDHL, satuan:'dS/m'}
};

function hitungKlasifikasi(){
  var errEl=document.getElementById('err-klasifikasi');
  var jenis=document.getElementById('klasifikasi-jenis').value;
  var nilai=parseFloat(document.getElementById('klasifikasi-nilai').value);
  if(isNaN(nilai)){ errEl.textContent='Isi nilai hasil analisis.'; errEl.style.display='block'; document.getElementById('hasil-klasifikasi').style.display='none'; return; }
  errEl.style.display='none';
  var m=klasifikasiMap[jenis];
  var label=document.getElementById('klasifikasi-jenis').selectedOptions[0].textContent;
  var status=m.fn(nilai);
  document.getElementById('klasifikasi-val').textContent=cap(status);
  document.getElementById('narasi-klasifikasi').textContent="Nilai "+label+" sebesar "+nilai+" "+m.satuan+" tergolong ke dalam kategori "+status+".";
  document.getElementById('hasil-klasifikasi').style.display='block';
}

function hitungPorositas(){
  var errEl=document.getElementById('err-poros');
  var vol=parseFloat(document.getElementById('poros-volume').value);
  var berat=parseFloat(document.getElementById('poros-berat').value);
  var pdMode = document.querySelector('input[name="poros-pd-mode"]:checked').value;
  var pd, pdLabel;

  if(isNaN(vol) || isNaN(berat) || vol<=0 || berat<=0){
    errEl.textContent='Isi massa tanah kering dan volume ring/sampel dengan angka positif yang valid.';
    errEl.style.display='block'; document.getElementById('hasil-poros').style.display='none'; return;
  }

  var bd = berat / vol;

  if(pdMode === 'asumsi'){
    pd = 2.65;
    pdLabel = 'PD (asumsi 2,65 g/cm³)';
  } else {
    var pdMassa = parseFloat(document.getElementById('poros-pd-massa').value);
    var pdVol = parseFloat(document.getElementById('poros-pd-vol').value);
    if(isNaN(pdMassa) || isNaN(pdVol) || pdMassa<=0 || pdVol<=0){
      errEl.textContent='Isi massa padatan kering dan volume padatan dengan angka positif yang valid untuk PD terukur.';
      errEl.style.display='block'; document.getElementById('hasil-poros').style.display='none'; return;
    }
    pd = pdMassa / pdVol;
    pdLabel = 'PD (terukur)';
  }

  if(bd >= pd){
    errEl.textContent='Berat Isi (BD) tidak boleh melebihi atau sama dengan Berat Jenis (PD). Periksa kembali data Anda.';
    errEl.style.display='block'; document.getElementById('hasil-poros').style.display='none'; return;
  }

  errEl.style.display='none';
  var trpFrac = 1 - (bd / pd);
  var trpPct = trpFrac * 100;

  document.getElementById('poros-bv-val').textContent = bd.toFixed(2) + ' g/cm³';
  document.getElementById('poros-pd-val').textContent = pd.toFixed(2) + ' g/cm³ (' + pdLabel + ')';
  document.getElementById('poros-val-frac').textContent = trpFrac.toFixed(4);
  document.getElementById('poros-val-pct').textContent = trpPct.toFixed(2) + '%';
  document.getElementById('narasi-poros').textContent = "Berat Isi (BD) sebesar " + bd.toFixed(2) + " g/cm3 dan porositas total " + poros.toFixed(1) + "% (" + c + "), dari massa tanah kering " + berat.toFixed(2) + " g dan volume ring " + vol.toFixed(2) + " cm3.";
  document.getElementById('hasil-poros').style.display='block';
}

function hitungDistribusiPartikel(){
  var errEl=document.getElementById('err-dup');
  var total=parseFloat(document.getElementById('dup-total').value), pasir=parseFloat(document.getElementById('dup-pasir').value);
  var debu=parseFloat(document.getElementById('dup-debu').value), liat=parseFloat(document.getElementById('dup-liat').value);
  if([total,pasir,debu,liat].some(isNaN) || total<=0 || pasir<0 || debu<0 || liat<0){ errEl.textContent='Isi berat total dan ketiga berat fraksi (semua > 0).'; errEl.style.display='block'; document.getElementById('hasil-dup').style.display='none'; return; }
  errEl.style.display='none';
  var pPasir=(pasir/total)*100, pDebu=(debu/total)*100, pLiat=(liat/total)*100;
  var jumlahFraksi=pasir+debu+liat;
  var kelas=getTexture(pPasir,pDebu,pLiat);
  document.getElementById('dup-pasir-val').textContent=pPasir.toFixed(1)+'%';
  document.getElementById('dup-debu-val').textContent=pDebu.toFixed(1)+'%';
  document.getElementById('dup-liat-val').textContent=pLiat.toFixed(1)+'%';
  document.getElementById('dup-tekstur-val').textContent=cap(kelas);
  var catatan = Math.abs(jumlahFraksi-total) > total*0.05 ? " Catatan: jumlah berat ketiga fraksi ("+jumlahFraksi.toFixed(2)+" g) berselisih cukup jauh dari berat total contoh, kemungkinan ada bahan (misalnya bahan organik) yang hilang saat pretreatment atau kesalahan penimbangan — cek kembali datanya." : "";
  document.getElementById('narasi-dup').textContent="Dari berat total contoh "+total.toFixed(2)+" g dengan fraksi pasir "+pasir.toFixed(2)+" g, debu "+debu.toFixed(2)+" g, dan liat "+liat.toFixed(2)+" g, diperoleh persentase pasir "+pPasir.toFixed(1)+"%, debu "+pDebu.toFixed(1)+"%, dan liat "+pLiat.toFixed(1)+"%, yang tergolong ke dalam kelas tekstur "+kelas+" menurut segitiga tekstur USDA."+catatan;
  document.getElementById('hasil-dup').style.display='block';
}

function hitungKadarAirVolumetrik(){
  var errEl=document.getElementById('err-kav');
  var grav=parseFloat(document.getElementById('kav-grav').value), bv=parseFloat(document.getElementById('kav-bv').value);
  if(isNaN(grav)||isNaN(bv)||grav<0||bv<=0){ errEl.textContent='Isi kadar air gravimetrik dan BV (BV > 0).'; errEl.style.display='block'; document.getElementById('hasil-kav').style.display='none'; return; }
  errEl.style.display='none';
  var kav=grav*bv;
  document.getElementById('kav-val').textContent=kav.toFixed(1)+'%';
  document.getElementById('narasi-kav').textContent="Berdasarkan kadar air gravimetrik sebesar "+grav.toFixed(1)+"% dan BV tanah sebesar "+bv.toFixed(2)+" g/cm3, diperoleh kadar air volumetrik sebesar "+kav.toFixed(1)+"% (dengan asumsi densitas air 1 g/cm3). Nilai ini dapat digunakan lebih lanjut untuk menghitung Water Filled Pore Space (WFPS).";
  document.getElementById('hasil-kav').style.display='block';
}

function hitungWFPS(){
  var errEl=document.getElementById('err-wfps');
  var kav=parseFloat(document.getElementById('wfps-kav').value), poros=parseFloat(document.getElementById('wfps-poros').value);
  if(isNaN(kav)||isNaN(poros)||kav<0||poros<=0){ errEl.textContent='Isi kadar air volumetrik dan porositas (porositas > 0).'; errEl.style.display='block'; document.getElementById('hasil-wfps').style.display='none'; return; }
  errEl.style.display='none';
  var wfps=(kav/poros)*100;
  var c=classifyWFPS(wfps);
  document.getElementById('wfps-val').textContent=wfps.toFixed(1)+'%';
  document.getElementById('wfps-out').textContent=cap(c);
  document.getElementById('narasi-wfps').textContent="Berdasarkan kadar air volumetrik sebesar "+kav.toFixed(1)+"% dan porositas total sebesar "+poros.toFixed(1)+"%, diperoleh WFPS sebesar "+wfps.toFixed(1)+"% yang tergolong "+c+". WFPS sekitar 60% umumnya dianggap optimal untuk respirasi aerob mikroba tanah, sedangkan nilai tinggi mendorong proses anaerob seperti denitrifikasi.";
  document.getElementById('hasil-wfps').style.display='block';
}

function hitungInfiltrasiKumulatif(){
  var errEl=document.getElementById('err-infil');
  var volume=parseFloat(document.getElementById('infil-volume').value), luas=parseFloat(document.getElementById('infil-luas').value), waktu=parseFloat(document.getElementById('infil-waktu').value);
  if([volume,luas,waktu].some(isNaN) || volume<0 || luas<=0 || waktu<=0){ errEl.textContent='Isi volume, luas ring, dan waktu (luas dan waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-infil').style.display='none'; return; }
  errEl.style.display='none';
  var kumulatif=volume/luas;
  var laju=kumulatif/(waktu/60);
  var c=classifyPermea(laju);
  document.getElementById('infil-kumulatif-val').textContent=kumulatif.toFixed(2)+' cm';
  document.getElementById('infil-laju-val').textContent=laju.toFixed(2)+' cm/jam';
  document.getElementById('infil-out').textContent=cap(c);
  document.getElementById('narasi-infil').textContent="Berdasarkan volume air yang meresap sebesar "+volume.toFixed(1)+" ml pada ring seluas "+luas.toFixed(1)+" cm2 selama "+waktu.toFixed(1)+" menit, diperoleh infiltrasi kumulatif sebesar "+kumulatif.toFixed(2)+" cm dengan laju infiltrasi rata-rata "+laju.toFixed(2)+" cm/jam, yang tergolong kelas permeabilitas "+c+".";
  document.getElementById('hasil-infil').style.display='block';
}

function hitungKs(){
  var errEl=document.getElementById('err-ks');
  var q=parseFloat(document.getElementById('ks-q').value), l=parseFloat(document.getElementById('ks-l').value);
  var a=parseFloat(document.getElementById('ks-a').value), h=parseFloat(document.getElementById('ks-h').value), t=parseFloat(document.getElementById('ks-t').value);
  if([q,l,a,h,t].some(isNaN) || q<0 || l<=0 || a<=0 || h<=0 || t<=0){ errEl.textContent='Isi semua nilai Q, L, A, H, dan waktu (semua > 0).'; errEl.style.display='block'; document.getElementById('hasil-ks').style.display='none'; return; }
  errEl.style.display='none';
  var ks=(q*l)/(a*h*t);
  var c=classifyPermea(ks);
  document.getElementById('ks-val').textContent=ks.toFixed(3)+' cm/jam';
  document.getElementById('ks-out').textContent=cap(c);
  document.getElementById('narasi-ks').textContent="Menggunakan metode constant head (Hukum Darcy) dengan volume air "+q.toFixed(1)+" cm3, panjang sampel "+l.toFixed(1)+" cm, luas penampang "+a.toFixed(1)+" cm2, tinggi tekanan hidrolik "+h.toFixed(1)+" cm, dan waktu "+t.toFixed(2)+" jam, diperoleh konduktivitas hidraulik jenuh (Ks) sebesar "+ks.toFixed(3)+" cm/jam yang tergolong kelas "+c+".";
  document.getElementById('hasil-ks').style.display='block';
}

function hitungFisika(){
  var errEl=document.getElementById('err-fisika');
  var bv=parseFloat(document.getElementById('bv').value);
  var pdMode = document.querySelector('input[name="fisika-pd-mode"]:checked').value;
  var pd, pdLabel;

  if(isNaN(bv) || bv<=0){
    errEl.textContent='Isi nilai Berat Isi / BD dengan angka positif yang valid.';
    errEl.style.display='block'; document.getElementById('hasil-fisika').style.display='none'; return;
  }

  if(pdMode === 'asumsi'){
    pd = 2.65;
    pdLabel = 'PD (asumsi 2,65 g/cm³)';
  } else {
    var pdMassa = parseFloat(document.getElementById('fisika-pd-massa').value);
    var pdVol = parseFloat(document.getElementById('fisika-pd-vol').value);
    if(isNaN(pdMassa) || isNaN(pdVol) || pdMassa<=0 || pdVol<=0){
      errEl.textContent='Isi massa padatan kering dan volume padatan dengan angka positif yang valid untuk PD terukur.';
      errEl.style.display='block'; document.getElementById('hasil-fisika').style.display='none'; return;
    }
    pd = pdMassa / pdVol;
    pdLabel = 'PD (terukur)';
  }

  if(bv >= pd){
    errEl.textContent='Berat Isi (BD) tidak boleh melebihi atau sama dengan Berat Jenis (PD). Periksa kembali data Anda.';
    errEl.style.display='block'; document.getElementById('hasil-fisika').style.display='none'; return;
  }

  errEl.style.display='none';
  var trpFrac = 1 - (bv / pd);
  var trpPct = trpFrac * 100;

  document.getElementById('fisika-pd-val').textContent = pd.toFixed(2) + ' g/cm³ (' + pdLabel + ')';
  document.getElementById('trp-val-frac').textContent = trpFrac.toFixed(4);
  document.getElementById('trp-val-pct').textContent = trpPct.toFixed(2) + '%';
  document.getElementById('narasi-fisika').textContent = "Berdasarkan nilai Berat Isi (BD) sebesar " + bv.toFixed(2) + " g/cm³ dan " + pdLabel + " sebesar " + pd.toFixed(2) + " g/cm³, diperoleh Total Ruang Pori (TRP) sebesar " + trpFrac.toFixed(4) + " (" + trpPct.toFixed(2) + "%).";
  document.getElementById('hasil-fisika').style.display='block';
}

function hitungTekstur(){
  var errEl=document.getElementById('err-tekstur');
  var pasir=parseFloat(document.getElementById('pasir').value), debu=parseFloat(document.getElementById('debu').value), liat=parseFloat(document.getElementById('liat').value);
  if(isNaN(pasir)||isNaN(debu)||isNaN(liat)){ errEl.textContent='Isi ketiga persentase (pasir, debu, liat) dulu ya.'; errEl.style.display='block'; document.getElementById('hasil-tekstur').style.display='none'; return; }
  var total=pasir+debu+liat;
  if(Math.abs(total-100)>2){ errEl.textContent='Total pasir+debu+liat harus sekitar 100% (saat ini '+total.toFixed(1)+'%).'; errEl.style.display='block'; document.getElementById('hasil-tekstur').style.display='none'; return; }
  errEl.style.display='none';
  var kelas=getTexture(pasir,debu,liat);
  document.getElementById('tekstur-out').textContent=cap(kelas);
  document.getElementById('narasi-tekstur').textContent="Berdasarkan komposisi fraksi pasir "+pasir.toFixed(1)+"%, debu "+debu.toFixed(1)+"%, dan liat "+liat.toFixed(1)+"%, sampel tanah tergolong ke dalam kelas tekstur "+kelas+" menurut segitiga tekstur USDA.";
  document.getElementById('hasil-tekstur').style.display='block';
}

function hitungKA(){
  var errEl=document.getElementById('err-ka');
  var wb=document.getElementById('beratbasah').value, wk=document.getElementById('beratkering').value;
  var r=window.SOILS_ENGINE.calculate('kadar_air_tanah',{berat_basah:wb,berat_kering:wk},{decimals:1});
  if(r.status!=='valid'){
    errEl.textContent=r.errors.join(' ')+(r.warnings.length?' ⚠️ '+r.warnings.join(' '):'');
    errEl.style.display='block'; document.getElementById('hasil-ka').style.display='none'; return;
  }
  errEl.textContent=r.warnings.length?'⚠️ '+r.warnings.join(' '):''; errEl.style.display=r.warnings.length?'block':'none';
  document.getElementById('hasil-ka').style.display='block';
  document.getElementById('ka-out').textContent=r.displayValue+'%';
  document.getElementById('narasi-ka').textContent=r.interpretation;
}

function hitungPermea(){
  var errEl=document.getElementById('err-permea');
  var v=parseFloat(document.getElementById('permea').value);
  if(isNaN(v)||v<0){ errEl.textContent='Isi laju infiltrasi.'; errEl.style.display='block'; document.getElementById('hasil-permea').style.display='none'; return; }
  errEl.style.display='none';
  var pC=classifyPermea(v);
  document.getElementById('permea-out').textContent=cap(pC);
  document.getElementById('narasi-permea').textContent="Berdasarkan hasil pengukuran, laju infiltrasi tanah sebesar "+v.toFixed(2)+" cm/jam yang tergolong ke dalam kelas permeabilitas "+pC+" menurut kriteria Balai Penelitian Tanah.";
  document.getElementById('hasil-permea').style.display='block';
}

function hitungAT(){
  var errEl=document.getElementById('err-at');
  var kl=parseFloat(document.getElementById('kl').value), tlp=parseFloat(document.getElementById('tlp').value);
  if(isNaN(kl)||isNaN(tlp)){ errEl.textContent='Isi Kapasitas Lapang dan Titik Layu Permanen.'; errEl.style.display='block'; document.getElementById('hasil-at').style.display='none'; return; }
  errEl.style.display='none';
  var at=kl-tlp;
  var atC=classifyAT(at);
  document.getElementById('at-val').textContent=at.toFixed(1)+'%';
  document.getElementById('at-out').textContent=cap(atC);
  document.getElementById('narasi-at').textContent="Berdasarkan Kapasitas Lapang sebesar "+kl.toFixed(1)+"% dan Titik Layu Permanen sebesar "+tlp.toFixed(1)+"%, diperoleh air tersedia bagi tanaman sebesar "+at.toFixed(1)+"% yang tergolong "+atC+".";
  document.getElementById('hasil-at').style.display='block';
}

function hitungTPC(){
  var errEl=document.getElementById('err-tpc');
  var koloni=parseFloat(document.getElementById('koloni').value), volume=parseFloat(document.getElementById('volume-tanam').value), pengenceran=parseFloat(document.getElementById('pengenceran').value);
  if(isNaN(koloni)||isNaN(volume)||isNaN(pengenceran)||volume<=0||pengenceran<=0){ errEl.textContent='Isi jumlah koloni, volume, dan pengenceran (volume dan pengenceran > 0).'; errEl.style.display='block'; document.getElementById('hasil-tpc').style.display='none'; return; }
  errEl.style.display='none';
  var n = koloni / (volume * pengenceran);
  document.getElementById('tpc-out').textContent = n.toExponential(2)+' CFU/g (atau CFU/ml, sesuaikan satuan sampel)';
  document.getElementById('narasi-tpc').textContent="Berdasarkan jumlah koloni terhitung sebanyak "+koloni+" pada volume tanam "+volume+" ml dengan faktor pengenceran "+pengenceran+", diperoleh populasi mikroba sebesar "+n.toExponential(2)+" CFU/g (atau CFU/ml sesuai jenis sampel).";
  document.getElementById('hasil-tpc').style.display='block';
}

function hitungTPCKelompok(){
  var errEl=document.getElementById('err-tpck');
  var bKoloni=parseFloat(document.getElementById('tpck-bakteri-koloni').value), bVolume=parseFloat(document.getElementById('tpck-bakteri-volume').value), bPengenceran=parseFloat(document.getElementById('tpck-bakteri-pengenceran').value);
  var jKoloni=parseFloat(document.getElementById('tpck-jamur-koloni').value), jVolume=parseFloat(document.getElementById('tpck-jamur-volume').value), jPengenceran=parseFloat(document.getElementById('tpck-jamur-pengenceran').value);
  var aKoloni=parseFloat(document.getElementById('tpck-aktino-koloni').value), aVolume=parseFloat(document.getElementById('tpck-aktino-volume').value), aPengenceran=parseFloat(document.getElementById('tpck-aktino-pengenceran').value);
  var vals=[bKoloni,bVolume,bPengenceran,jKoloni,jVolume,jPengenceran,aKoloni,aVolume,aPengenceran];
  if(vals.some(isNaN) || bVolume<=0 || bPengenceran<=0 || jVolume<=0 || jPengenceran<=0 || aVolume<=0 || aPengenceran<=0){ errEl.textContent='Isi jumlah koloni, volume tanam, dan faktor pengenceran untuk ketiga kelompok mikroba dengan angka valid.'; errEl.style.display='block'; document.getElementById('hasil-tpck').style.display='none'; return; }
  errEl.style.display='none';
  var nBakteri = bKoloni/(bVolume*bPengenceran);
  var nJamur = jKoloni/(jVolume*jPengenceran);
  var nAktino = aKoloni/(aVolume*aPengenceran);
  document.getElementById('tpck-bakteri-val').textContent = nBakteri.toExponential(2)+' CFU/g';
  document.getElementById('tpck-jamur-val').textContent = nJamur.toExponential(2)+' CFU/g';
  document.getElementById('tpck-aktino-val').textContent = nAktino.toExponential(2)+' CFU/g';
  var rasioText, rasioC, rasioNarasi;
  if(nJamur<=0){
    rasioText='Tidak terhingga (jamur = 0)';
    rasioNarasi="Tidak ditemukan koloni jamur pada sampel, sehingga rasio bakteri:jamur tidak dapat dihitung secara numerik dan mengindikasikan populasi sangat bakteri-dominan.";
  } else {
    var rasio = nBakteri/nJamur;
    rasioC = classifyRasioBF(rasio);
    rasioText = rasio.toFixed(2)+' : 1 ('+rasioC+')';
    rasioNarasi = "Rasio bakteri terhadap jamur sebesar "+rasio.toFixed(2)+" : 1, tergolong "+rasioC+". Rasio yang lebih tinggi (bakteri-dominan) umumnya dikaitkan dengan dekomposisi bahan organik yang lebih cepat dan sering dianggap sebagai indikasi fungsi tanah yang lebih 'sehat' pada lahan pertanian, sedangkan rasio rendah (jamur-dominan) bisa merupakan kondisi normal pada tanah hutan/alami atau mengindikasikan gangguan (misalnya residu fungisida rendah, bahan organik berkayu tinggi) pada tanah pertanian intensif.";
  }
  document.getElementById('tpck-rasio-val').textContent = rasioText;
  var mediaNote = '';
  var mB=document.getElementById('tpck-bakteri-media').value, mJ=document.getElementById('tpck-jamur-media').value, mA=document.getElementById('tpck-aktino-media').value;
  if(mB||mJ||mA){ mediaNote = " Media yang digunakan: "+(mB||'-')+" (bakteri), "+(mJ||'-')+" (jamur), "+(mA||'-')+" (aktinomicetes)."; }
  document.getElementById('narasi-tpck').textContent = "Populasi mikroba tanah tercatat sebesar "+nBakteri.toExponential(2)+" CFU/g untuk bakteri, "+nJamur.toExponential(2)+" CFU/g untuk jamur, dan "+nAktino.toExponential(2)+" CFU/g untuk aktinomicetes. "+rasioNarasi+mediaNote;
  document.getElementById('hasil-tpck').style.display='block';
}

function hitungKeragaman(){
  var errEl=document.getElementById('err-keragaman');
  var ids=['keragaman-jenis1','keragaman-jenis2','keragaman-jenis3','keragaman-jenis4','keragaman-jenis5','keragaman-jenis6','keragaman-jenis7','keragaman-jenis8'];
  var counts=[];
  for(var i=0;i<ids.length;i++){
    var v=parseFloat(document.getElementById(ids[i]).value);
    if(!isNaN(v) && v>0) counts.push(v);
  }
  if(counts.length<1){ errEl.textContent='Isi jumlah koloni minimal untuk satu jenis.'; errEl.style.display='block'; document.getElementById('hasil-keragaman').style.display='none'; return; }
  errEl.style.display='none';
  var total=counts.reduce(function(a,b){return a+b;},0);
  var s=counts.length;
  var h=0;
  for(var j=0;j<counts.length;j++){
    var pi=counts[j]/total;
    h += pi*Math.log(pi);
  }
  h = -h;
  var jEven = s>1 ? (h/Math.log(s)) : null;
  var c = classifyShannon(h);
  document.getElementById('keragaman-s-val').textContent = s;
  document.getElementById('keragaman-h-val').textContent = h.toFixed(3);
  document.getElementById('keragaman-j-val').textContent = jEven===null ? 'N/A (hanya 1 jenis)' : jEven.toFixed(3);
  document.getElementById('keragaman-out').textContent = cap(c);
  document.getElementById('narasi-keragaman').textContent = "Berdasarkan "+s+" jenis mikroba dengan total "+total+" koloni, diperoleh indeks keragaman Shannon (H') sebesar "+h.toFixed(3)+" yang tergolong "+c+(jEven!==null ? ", dengan evenness (J) sebesar "+jEven.toFixed(3)+" yang menggambarkan seberapa merata proporsi tiap jenis" : "")+". Kategori keragaman ini bersifat indikatif dan dapat berbeda tergantung metode identifikasi (morfologi kasar vs molekuler) dan literatur acuan yang dipakai.";
  document.getElementById('hasil-keragaman').style.display='block';
}

function hitungStatusBiologi(){
  var errEl=document.getElementById('err-statusbio');
  var kelompok=document.getElementById('statusbio-kelompok').value;
  var tpc=parseFloat(document.getElementById('statusbio-tpc').value);
  if(isNaN(tpc) || tpc<0){ errEl.textContent='Isi nilai TPC.'; errEl.style.display='block'; document.getElementById('hasil-statusbio').style.display='none'; return; }
  errEl.style.display='none';
  var status=classifyStatusBio(tpc, kelompok);
  var label=document.getElementById('statusbio-kelompok').selectedOptions[0].textContent;
  document.getElementById('statusbio-out').textContent = cap(status);
  document.getElementById('narasi-statusbio').textContent = "Populasi "+label+" sebesar "+tpc.toExponential(2)+" CFU/g tergolong "+status+". Kondisi ini "+narasiBio[status]+". Ambang batas klasifikasi bersifat indikatif dan dapat bervariasi antar literatur/metode, sesuaikan dengan acuan modul praktikummu.";
  document.getElementById('hasil-statusbio').style.display='block';
}

function hitungRespirasi(){
  var errEl=document.getElementById('err-respirasi');
  var vb=parseFloat(document.getElementById('vb').value), vs=parseFloat(document.getElementById('vs').value), nhcl=parseFloat(document.getElementById('nhcl').value);
  var berat=parseFloat(document.getElementById('beratrespirasi').value), waktu=parseFloat(document.getElementById('waktuinkubasi').value);
  if([vb,vs,nhcl,berat,waktu].some(isNaN) || berat<=0 || waktu<=0){ errEl.textContent='Isi semua nilai titrasi, berat tanah, dan waktu (berat dan waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-respirasi').style.display='none'; return; }
  errEl.style.display='none';
  var co2 = (vb-vs)*nhcl*22;
  var fluks = co2/(berat*waktu);
  document.getElementById('co2-val').textContent = co2.toFixed(2)+' mg';
  document.getElementById('fluks-val').textContent = fluks.toFixed(2)+' mg CO2/kg/hari';
  document.getElementById('narasi-respirasi').textContent="Berdasarkan hasil titrasi (blanko "+vb.toFixed(2)+" ml, sampel "+vs.toFixed(2)+" ml, normalitas HCl "+nhcl.toFixed(3)+" N), dihasilkan CO2 sebesar "+co2.toFixed(2)+" mg, setara dengan fluks respirasi tanah sebesar "+fluks.toFixed(2)+" mg CO2/kg tanah/hari selama masa inkubasi "+waktu.toFixed(1)+" hari. Sesuaikan rumus dengan protokol laboratorium yang digunakan.";
  document.getElementById('hasil-respirasi').style.display='block';
}

/* ===================== Biologi tambahan (36-45) ===================== */

function hitungPopBakteri(){
  var errEl=document.getElementById('err-popbak');
  var koloni=parseFloat(document.getElementById('popbak-koloni').value), volume=parseFloat(document.getElementById('popbak-volume').value), pengenceran=parseFloat(document.getElementById('popbak-pengenceran').value);
  if([koloni,volume,pengenceran].some(isNaN) || volume<=0 || pengenceran<=0){ errEl.textContent='Isi jumlah koloni, volume, dan pengenceran (volume dan pengenceran > 0).'; errEl.style.display='block'; document.getElementById('hasil-popbak').style.display='none'; return; }
  errEl.style.display='none';
  var n = koloni/(volume*pengenceran);
  var c = classifyStatusBio(n, 'bakteri');
  document.getElementById('popbak-val').textContent = n.toExponential(2)+' CFU/g';
  document.getElementById('popbak-out').textContent = cap(c);
  document.getElementById('narasi-popbak').textContent = "Populasi bakteri tanah tercatat sebesar "+n.toExponential(2)+" CFU/g, tergolong "+c+". Kondisi ini "+narasiBio[c]+". Ambang batas klasifikasi bersifat indikatif, sesuaikan dengan acuan modul praktikummu.";
  document.getElementById('hasil-popbak').style.display='block';
}

