function classifyBMC(v){ if(v<100) return "rendah"; if(v<300) return "sedang"; if(v<600) return "tinggi"; return "sangat tinggi"; }
function hitungBMC(){
  var errEl=document.getElementById('err-bmc');
  var fum=parseFloat(document.getElementById('bmc-fum').value), nonfum=parseFloat(document.getElementById('bmc-nonfum').value);
  var kecRaw=document.getElementById('bmc-kec').value; var kec=kecRaw===''?0.45:parseFloat(kecRaw);
  if([fum,nonfum,kec].some(isNaN) || kec<=0){ errEl.textContent='Isi nilai C fumigasi, non-fumigasi, dan kEC (kEC > 0).'; errEl.style.display='block'; document.getElementById('hasil-bmc').style.display='none'; return; }
  errEl.style.display='none';
  var cmic=(fum-nonfum)/kec;
  var c=classifyBMC(cmic);
  document.getElementById('bmc-val').textContent=cmic.toFixed(1)+' mg C/kg tanah';
  document.getElementById('bmc-out').textContent=cap(c);
  document.getElementById('narasi-bmc').textContent="Berdasarkan selisih C-organik terekstrak antara tanah difumigasi ("+fum.toFixed(1)+" mg C/kg) dan non-fumigasi ("+nonfum.toFixed(1)+" mg C/kg) dengan faktor koreksi kEC="+kec+", diperoleh biomassa mikroba-C sebesar "+cmic.toFixed(1)+" mg C/kg tanah yang tergolong "+c+". Nilai ini mencerminkan ukuran populasi mikroba aktif sebagai bagian dari bahan organik tanah yang mudah terurai.";
  document.getElementById('hasil-bmc').style.display='block';
}

function classifyBMN(v){ if(v<10) return "rendah"; if(v<25) return "sedang"; if(v<50) return "tinggi"; return "sangat tinggi"; }
function hitungBMN(){
  var errEl=document.getElementById('err-bmn');
  var fum=parseFloat(document.getElementById('bmn-fum').value), nonfum=parseFloat(document.getElementById('bmn-nonfum').value);
  var kenRaw=document.getElementById('bmn-ken').value; var ken=kenRaw===''?0.54:parseFloat(kenRaw);
  if([fum,nonfum,ken].some(isNaN) || ken<=0){ errEl.textContent='Isi nilai N fumigasi, non-fumigasi, dan kEN (kEN > 0).'; errEl.style.display='block'; document.getElementById('hasil-bmn').style.display='none'; return; }
  errEl.style.display='none';
  var nmic=(fum-nonfum)/ken;
  var c=classifyBMN(nmic);
  document.getElementById('bmn-val').textContent=nmic.toFixed(1)+' mg N/kg tanah';
  document.getElementById('bmn-out').textContent=cap(c);
  document.getElementById('narasi-bmn').textContent="Berdasarkan selisih N terekstrak antara tanah difumigasi ("+fum.toFixed(1)+" mg N/kg) dan non-fumigasi ("+nonfum.toFixed(1)+" mg N/kg) dengan faktor koreksi kEN="+ken+", diperoleh biomassa mikroba-N sebesar "+nmic.toFixed(1)+" mg N/kg tanah yang tergolong "+c+". Biomassa mikroba-N menggambarkan cadangan N yang tersimpan dalam sel mikroba dan berpotensi dilepas kembali ke tanah melalui mineralisasi.";
  document.getElementById('hasil-bmn').style.display='block';
}

function classifyNmin(v){ if(v<0) return "immobilisasi neto (net negatif)"; if(v<0.5) return "mineralisasi rendah"; if(v<1.5) return "mineralisasi sedang"; return "mineralisasi tinggi"; }
function hitungNmin(){
  var errEl=document.getElementById('err-nmin');
  var nh4a=parseFloat(document.getElementById('nmin-nh4awal').value), no3a=parseFloat(document.getElementById('nmin-no3awal').value);
  var nh4b=parseFloat(document.getElementById('nmin-nh4akhir').value), no3b=parseFloat(document.getElementById('nmin-no3akhir').value);
  var waktu=parseFloat(document.getElementById('nmin-waktu').value);
  if([nh4a,no3a,nh4b,no3b,waktu].some(isNaN) || waktu<=0){ errEl.textContent='Isi nilai NH4/NO3 awal-akhir dan waktu (waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-nmin').style.display='none'; return; }
  errEl.style.display='none';
  var total=(nh4b+no3b)-(nh4a+no3a);
  var laju=total/waktu;
  var c=classifyNmin(laju);
  document.getElementById('nmin-total-val').textContent=total.toFixed(2)+' mg N/kg';
  document.getElementById('nmin-laju-val').textContent=laju.toFixed(3)+' mg N/kg/hari';
  document.getElementById('nmin-out').textContent=cap(c);
  document.getElementById('narasi-nmin').textContent="Selama masa inkubasi "+waktu.toFixed(1)+" hari, N mineral (NH4+NO3) berubah dari "+(nh4a+no3a).toFixed(2)+" menjadi "+(nh4b+no3b).toFixed(2)+" mg N/kg, sehingga diperoleh N mineral bersih sebesar "+total.toFixed(2)+" mg N/kg atau laju "+laju.toFixed(3)+" mg N/kg/hari yang tergolong "+c+". Nilai negatif mengindikasikan immobilisasi N oleh mikroba (net konsumsi N mineral), sedangkan nilai positif menunjukkan pelepasan N mineral neto ke dalam larutan tanah.";
  document.getElementById('hasil-nmin').style.display='block';
}

function classifyNitrifPersen(v){ if(v<25) return "rendah (amonifikasi lebih dominan)"; if(v<75) return "sedang"; return "tinggi (nitrifikasi dominan)"; }
function hitungNitrifikasi(){
  var errEl=document.getElementById('err-nitrif');
  var no3a=parseFloat(document.getElementById('nitrif-no3awal').value), no3b=parseFloat(document.getElementById('nitrif-no3akhir').value);
  var nh4b=parseFloat(document.getElementById('nitrif-nh4akhir').value), waktu=parseFloat(document.getElementById('nitrif-waktu').value);
  if([no3a,no3b,nh4b,waktu].some(isNaN) || waktu<=0 || (no3b+nh4b)<=0){ errEl.textContent='Isi nilai NO3, NH4, dan waktu (waktu > 0, total N akhir > 0).'; errEl.style.display='block'; document.getElementById('hasil-nitrif').style.display='none'; return; }
  errEl.style.display='none';
  var laju=(no3b-no3a)/waktu;
  var persen=(no3b/(no3b+nh4b))*100;
  var c=classifyNitrifPersen(persen);
  document.getElementById('nitrif-laju-val').textContent=laju.toFixed(3)+' mg N/kg/hari';
  document.getElementById('nitrif-persen-val').textContent=persen.toFixed(1)+'%';
  document.getElementById('nitrif-out').textContent=cap(c);
  document.getElementById('narasi-nitrif').textContent="NO3-N meningkat dari "+no3a.toFixed(2)+" menjadi "+no3b.toFixed(2)+" mg N/kg selama "+waktu.toFixed(1)+" hari, setara laju nitrifikasi "+laju.toFixed(3)+" mg N/kg/hari. Proporsi NO3 terhadap total N mineral akhir sebesar "+persen.toFixed(1)+"%, tergolong "+c+". Nitrifikasi yang tinggi menandakan konversi amonium ke nitrat berjalan aktif, namun juga berisiko lebih besar terhadap pencucian nitrat (leaching).";
  document.getElementById('hasil-nitrif').style.display='block';
}

function classifyDHA(v){ if(v<20) return "rendah"; if(v<60) return "sedang"; if(v<120) return "tinggi"; return "sangat tinggi"; }
function hitungDHA(){
  var errEl=document.getElementById('err-dha');
  var konsentrasi=parseFloat(document.getElementById('dha-konsentrasi').value), volume=parseFloat(document.getElementById('dha-volume').value), berat=parseFloat(document.getElementById('dha-berat').value);
  if([konsentrasi,volume,berat].some(isNaN) || berat<=0){ errEl.textContent='Isi konsentrasi TPF, volume ekstrak, dan berat (berat > 0).'; errEl.style.display='block'; document.getElementById('hasil-dha').style.display='none'; return; }
  errEl.style.display='none';
  var aktivitas=(konsentrasi*volume)/berat;
  var c=classifyDHA(aktivitas);
  document.getElementById('dha-val').textContent=aktivitas.toFixed(2)+' µg TPF/g tanah/24 jam';
  document.getElementById('dha-out').textContent=cap(c);
  document.getElementById('narasi-dha').textContent="Berdasarkan konsentrasi TPF "+konsentrasi.toFixed(2)+" µg/ml pada volume ekstrak "+volume.toFixed(1)+" ml dan berat tanah "+berat.toFixed(2)+" g, diperoleh aktivitas enzim dehidrogenase sebesar "+aktivitas.toFixed(2)+" µg TPF/g tanah/24 jam yang tergolong "+c+". Enzim dehidrogenase mencerminkan aktivitas respirasi/metabolisme mikroba tanah secara keseluruhan.";
  document.getElementById('hasil-dha').style.display='block';
}

