  if([konsentrasi,volume,berat,waktu].some(isNaN) || berat<=0 || waktu<=0){ errEl.textContent='Isi konsentrasi NH4, volume, berat, dan waktu (berat dan waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-urease').style.display='none'; return; }
