  if([konsentrasi,volume,berat,waktu].some(isNaN) || berat<=0 || waktu<=0){ errEl.textContent='Isi konsentrasi PNP, volume, berat, dan waktu (berat dan waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-fosfatase').style.display='none'; return; }
