  var konsentrasi=parseFloat(document.getElementById('glukosidase-konsentrasi').value), volume=parseFloat(document.getElementById('glukosidase-volume').value), berat=parseFloat(document.getElementById('glukosidase-berat').value), waktu=parseFloat(document.getElementById('glukosidase-waktu').value);
  if([konsentrasi,volume,berat,waktu].some(isNaN) || berat<=0 || waktu<=0){ errEl.textContent='Isi konsentrasi PNP, volume, berat, dan waktu (berat dan waktu > 0).'; errEl.style.display='block'; document.getElementById('hasil-glukosidase').style.display='none'; return; }
