  if([vk,n,s,t,berat,fk].some(isNaN) || vk<=0 || n<=0 || s<=0 || t<0 || berat<=0 || fk<=0){ errEl.textContent='Isi semua kolom. Hanya volume titrasi sampel yang boleh 0.'; errEl.style.display='block'; document.getElementById('hasil-corgmentah').style.display='none'; return; }
  if(t>=s){ errEl.textContent='T harus lebih kecil dari S. Periksa lagi data titrasi.'; errEl.style.display='block'; document.getElementById('hasil-corgmentah').style.display='none'; return; }
  errEl.style.display='none';
