var BE_KATION = { ca: 20.04, mg: 12.16, k: 39.10, na: 22.99 };
var NAMA_KATION = { ca: 'Ca', mg: 'Mg', k: 'K', na: 'Na' };
function hitungBasaMentah(){
  var errEl=document.getElementById('err-basamentah');
  var kation=document.getElementById('basamentah-kation').value;
  var ppm=parseFloat(document.getElementById('basamentah-ppm').value), vekstrak=parseFloat(document.getElementById('basamentah-vekstrak').value), fp=parseFloat(document.getElementById('basamentah-fp').value), berat=parseFloat(document.getElementById('basamentah-berat').value);
  if([ppm,vekstrak,fp,berat].some(isNaN) || ppm<0 || vekstrak<=0 || fp<=0 || berat<=0){ errEl.textContent='Isi semua kolom (kolom selain ppm harus > 0).'; errEl.style.display='block'; document.getElementById('hasil-basamentah').style.display='none'; return; }
  errEl.style.display='none';
  var be=BE_KATION[kation];
  var kadar=(ppm*vekstrak*fp)/(be*berat*10);
  var namaK=NAMA_KATION[kation];
  var statusText, narasiStatus;
  if(kation==='k'){
    statusText=cap(classifyK(kadar));
    narasiStatus=", yang tergolong "+classifyK(kadar)+" menurut kriteria Pusat Penelitian Tanah (Balai Penelitian Tanah, 1983)";
  } else {
    statusText='Lihat kalkulator Kejenuhan '+namaK+' (bagian 12-15)';
    narasiStatus="";
  }
  document.getElementById('basamentah-val').textContent=kadar.toFixed(3)+' me/100g';
  document.getElementById('basamentah-status-val').textContent=statusText;
  document.getElementById('narasi-basamentah').textContent="Dari pembacaan AAS/flamefotometer sebesar "+ppm+" ppm "+namaK+", volume ekstrak "+vekstrak+" mL, faktor pengenceran "+fp+" kali, dan berat contoh "+berat+" g (dengan berat ekivalen "+namaK+" = "+be+"), diperoleh kadar "+namaK+"-tukar sebesar "+kadar.toFixed(3)+" me/100g"+narasiStatus+". Nilai ini dapat dipakai sebagai input pada kalkulator Kejenuhan Basa (bagian 2) atau kalkulator Kejenuhan "+namaK+" (bagian 12-15) untuk menghitung persen kejenuhannya terhadap KTK.";
  document.getElementById('hasil-basamentah').style.display='block';
}

