/* ===== Helper umum statistik ===== */
function normalizeUserInputValue(raw){
  var s=String(raw==null?'':raw).replace(/\u00A0/g,' ').trim();
  if(!s) return '';

  /* Samakan semua jenis dash dan rapikan spasi di sekitar pemisah.
     Contoh: 32 – 26 , 29  ->  32-26,29 */
  s=s.replace(/[\u2010-\u2015\u2212]/g,'-');
  s=s.replace(/\s*[-]\s*/g,'-');
  s=s.replace(/\s*[,;]\s*/g,',');

  /* Untuk satu angka saja, izinkan koma sebagai desimal.
     Jika ada beberapa koma, koma dipertahankan sebagai pemisah data. */
  if(/^[+-]?\d+,\d+$/.test(s)) s=s.replace(',', '.');
  else if(/^[+-]?\d{1,3}(?:\.\d{3})+,\d+$/.test(s)) s=s.replace(/\./g,'').replace(',', '.');

  return s;
}

function parseFlexibleNumber(token){
  var s=String(token==null?'':token).trim();
  if(!s) return NaN;
  s=s.replace(/\u00A0/g,'').replace(/[\u2010-\u2015\u2212]/g,'-');
  /* Format Indonesia: 1.250,5 -> 1250.5 */
  if(/^[-+]?\d{1,3}(?:\.\d{3})+,\d+$/.test(s)) s=s.replace(/\./g,'').replace(',', '.');
  else if(/^[-+]?\d+,\d+$/.test(s)) s=s.replace(',', '.');
  return Number(s);
}

function parseNumberList(text){
  if(!text) return [];
  var raw=String(text).replace(/\u00A0/g,' ').trim();
  if(!raw) return [];

  /* Semicolon/newline selalu aman sebagai pemisah data.
     Koma dipakai sebagai pemisah hanya bila ada lebih dari satu koma;
     satu koma pada satu angka dibaca sebagai desimal. */
  var parts;
  if(/[;\n]/.test(raw)) parts=raw.split(/[;\n]+/);
  else {
    var commaCount=(raw.match(/,/g)||[]).length;
    if(commaCount===1 && /^[+-]?\d+,\d+$/.test(raw.trim())) parts=[raw];
    else parts=raw.split(/[,\s]+/);
  }
  return parts.map(function(s){return s.trim();})
    .filter(function(s){return s.length>0;})
    .map(parseFlexibleNumber)
    .filter(function(v){return !isNaN(v);});
}
function statMean(arr){ return arr.reduce(function(a,b){return a+b;},0)/arr.length; }
function statMedian(arr){
  var s=arr.slice().sort(function(a,b){return a-b;});
  var n=s.length, mid=Math.floor(n/2);
  return (n%2!==0) ? s[mid] : (s[mid-1]+s[mid])/2;
}
function statVariance(arr){
  var n=arr.length, m=statMean(arr);
  return arr.reduce(function(a,b){return a+Math.pow(b-m,2);},0)/(n-1);
}
function statSD(arr){ return Math.sqrt(statVariance(arr)); }
function statMode(arr){
  var freq={}, order=[];
  arr.forEach(function(v){
    var key=v.toPrecision(10);
    if(!(key in freq)){ freq[key]=0; order.push(key); }
    freq[key]++;
  });
  var maxFreq=0;
  order.forEach(function(k){ if(freq[k]>maxFreq) maxFreq=freq[k]; });
  if(maxFreq<=1) return { modes: [], freq: 0 };
  var modes=order.filter(function(k){ return freq[k]===maxFreq; }).map(parseFloat).sort(function(a,b){return a-b;});
  return { modes: modes, freq: maxFreq };
}
function percentile(sortedArr, p){
  var n=sortedArr.length;
  if(n===1) return sortedArr[0];
  var rank=p*(n-1), lo=Math.floor(rank), hi=Math.ceil(rank);
  if(lo===hi) return sortedArr[lo];
  return sortedArr[lo] + (sortedArr[hi]-sortedArr[lo])*(rank-lo);
}
function pearsonR(x,y){
  var n=x.length;
  var sumX=0,sumY=0,sumXY=0,sumX2=0,sumY2=0;
  for(var i=0;i<n;i++){ sumX+=x[i]; sumY+=y[i]; sumXY+=x[i]*y[i]; sumX2+=x[i]*x[i]; sumY2+=y[i]*y[i]; }
  var num=(n*sumXY)-(sumX*sumY);
  var den=Math.sqrt(((n*sumX2)-(sumX*sumX))*((n*sumY2)-(sumY*sumY)));
  if(den===0) return 0;
  return num/den;
}
function linearRegression(x,y){
  var n=x.length;
  var sumX=0,sumY=0,sumXY=0,sumX2=0;
  for(var i=0;i<n;i++){ sumX+=x[i]; sumY+=y[i]; sumXY+=x[i]*y[i]; sumX2+=x[i]*x[i]; }
  var denom=(n*sumX2)-(sumX*sumX);
  var b = denom===0 ? 0 : ((n*sumXY)-(sumX*sumY))/denom;
  var a = (sumY-b*sumX)/n;
  var r = pearsonR(x,y);
  return {a:a, b:b, r2:r*r};
}
function classifyR(r){
  var abs=Math.abs(r);
  var kekuatan;
  if(abs<0.2) kekuatan="sangat lemah";
  else if(abs<0.4) kekuatan="lemah";
  else if(abs<0.6) kekuatan="sedang";
  else if(abs<0.8) kekuatan="kuat";
  else kekuatan="sangat kuat";
  var arah = r>0.0001 ? "positif" : (r<-0.0001 ? "negatif" : "tidak berarah (nol)");
  return kekuatan+", "+arah;
}
function clearChart(ctx,w,h){ ctx.clearRect(0,0,w,h); ctx.fillStyle="#fbfaf7"; ctx.fillRect(0,0,w,h); }
function hexToRgb(hex){ hex=hex.replace('#',''); return {r:parseInt(hex.substring(0,2),16), g:parseInt(hex.substring(2,4),16), b:parseInt(hex.substring(4,6),16)}; }
function interpolateColor(hex1,hex2,t){
  var c1=hexToRgb(hex1), c2=hexToRgb(hex2);
  var r=Math.round(c1.r+(c2.r-c1.r)*t), g=Math.round(c1.g+(c2.g-c1.g)*t), b=Math.round(c1.b+(c2.b-c1.b)*t);
  return 'rgb('+r+','+g+','+b+')';
}
function corrColor(r){
  if(r>=0) return interpolateColor('#ffffff','#7f77dd', Math.min(1,r));
  return interpolateColor('#ffffff','#d98a8a', Math.min(1,Math.abs(r)));
}

/* ===== 65. Statistik Deskriptif ===== */
function hitungDeskriptif(){
  var errEl=document.getElementById('err-desk');
  var data=parseNumberList(document.getElementById('desk-data').value);
  if(data.length<2){ errEl.textContent='Masukkan minimal 2 data numerik yang valid.'; errEl.style.display='block'; document.getElementById('hasil-desk').style.display='none'; return; }
  errEl.style.display='none';
  var n=data.length, mean=statMean(data), median=statMedian(data), min=Math.min.apply(null,data), max=Math.max.apply(null,data);
  var range=max-min, variance=statVariance(data), sd=Math.sqrt(variance), cv=(sd/mean)*100, se=sd/Math.sqrt(n);
  var modeRes=statMode(data);
  var modusText, modusNarasi;
  if(modeRes.modes.length===0){
    modusText='Tidak ada (semua data unik)';
    modusNarasi='tidak ditemukan modus karena setiap nilai data hanya muncul satu kali (semua data unik)';
  } else if(modeRes.modes.length===1){
    modusText=modeRes.modes[0].toPrecision(4)+' (muncul '+modeRes.freq+'x)';
    modusNarasi='modus (nilai yang paling sering muncul) sebesar '+modeRes.modes[0].toPrecision(4)+', muncul sebanyak '+modeRes.freq+' kali';
  } else {
    var modusList=modeRes.modes.map(function(m){return m.toPrecision(4);}).join(', ');
    modusText=modusList+' (multimodal, masing-masing '+modeRes.freq+'x)';
    modusNarasi='data bersifat multimodal dengan '+modeRes.modes.length+' modus, yaitu '+modusList+', masing-masing muncul sebanyak '+modeRes.freq+' kali';
  }
  document.getElementById('desk-n').textContent=n;
  document.getElementById('desk-mean').textContent=mean.toPrecision(4);
  document.getElementById('desk-median').textContent=median.toPrecision(4);
  document.getElementById('desk-modus').textContent=modusText;
  document.getElementById('desk-min').textContent=min.toPrecision(4);
  document.getElementById('desk-max').textContent=max.toPrecision(4);
  document.getElementById('desk-range').textContent=range.toPrecision(4);
  document.getElementById('desk-sd').textContent=sd.toPrecision(4);
  document.getElementById('desk-var').textContent=variance.toPrecision(4);
  document.getElementById('desk-cv').textContent=cv.toFixed(2)+'%';
  document.getElementById('desk-se').textContent=se.toPrecision(4);
  var keragaman = cv<10 ? "rendah (data relatif homogen)" : (cv<30 ? "sedang" : "tinggi (data cukup beragam)");
  document.getElementById('narasi-desk').textContent="Dari "+n+" data diperoleh rata-rata (mean) sebesar "+mean.toPrecision(4)+" dengan median "+median.toPrecision(4)+", nilai minimum "+min.toPrecision(4)+" dan maksimum "+max.toPrecision(4)+" (range "+range.toPrecision(4)+"). Pada data ini "+modusNarasi+". Standar deviasi sebesar "+sd.toPrecision(4)+" dan coefficient of variation (CV) "+cv.toFixed(2)+"% menunjukkan tingkat keragaman data yang tergolong "+keragaman+". Standard error (SE) rata-rata sebesar "+se.toPrecision(4)+".";
  document.getElementById('hasil-desk').style.display='block';
}

/* ===== 66. Confidence Interval ===== */
function hitungCI(){
  var errEl=document.getElementById('err-ci');
  var data=parseNumberList(document.getElementById('ci-data').value);
  var z=parseFloat(document.getElementById('ci-level').value);
  var levelLabel=document.getElementById('ci-level').selectedOptions ? document.getElementById('ci-level').selectedOptions[0].textContent : (z===1.96?'95%':(z===1.645?'90%':'99%'));
  if(data.length<2){ errEl.textContent='Masukkan minimal 2 data numerik yang valid.'; errEl.style.display='block'; document.getElementById('hasil-ci').style.display='none'; return; }
  errEl.style.display='none';
  var n=data.length, mean=statMean(data), sd=statSD(data), se=sd/Math.sqrt(n);
  var lower=mean-z*se, upper=mean+z*se;
  document.getElementById('ci-mean').textContent=mean.toPrecision(4);
  document.getElementById('ci-se').textContent=se.toPrecision(4);
  document.getElementById('ci-lower').textContent=lower.toPrecision(4);
  document.getElementById('ci-upper').textContent=upper.toPrecision(4);
  document.getElementById('narasi-ci').textContent="Dari "+n+" data dengan rata-rata "+mean.toPrecision(4)+" dan standard error "+se.toPrecision(4)+", diperoleh confidence interval "+levelLabel+" untuk rata-rata populasi antara "+lower.toPrecision(4)+" hingga "+upper.toPrecision(4)+". Artinya, dengan tingkat kepercayaan "+levelLabel+", rata-rata populasi sebenarnya diperkirakan berada pada rentang tersebut.";
  document.getElementById('hasil-ci').style.display='block';
}

/* ===== 67. Korelasi ===== */
function hitungKorelasi(){
  var errEl=document.getElementById('err-korel');
  var x=parseNumberList(document.getElementById('korel-x').value);
  var y=parseNumberList(document.getElementById('korel-y').value);
  if(x.length<2 || y.length<2 || x.length!==y.length){ errEl.textContent='Isi data X dan Y dengan angka valid, jumlah data X dan Y harus sama (minimal 2 pasang).'; errEl.style.display='block'; document.getElementById('hasil-korel').style.display='none'; return; }
  errEl.style.display='none';
  var r=pearsonR(x,y);
  document.getElementById('korel-n').textContent=x.length;
  document.getElementById('korel-r').textContent=r.toFixed(4);
  document.getElementById('korel-out').textContent=cap(classifyR(r));
  document.getElementById('narasi-korel').textContent="Dari "+x.length+" pasang data X dan Y, diperoleh koefisien korelasi Pearson (r) sebesar "+r.toFixed(4)+" yang tergolong "+classifyR(r)+", menunjukkan hubungan linear antara kedua variabel tersebut.";
  document.getElementById('hasil-korel').style.display='block';
}

/* ===== 68. Regresi Linear ===== */
function hitungRegresi(){
  var errEl=document.getElementById('err-reg');
  var x=parseNumberList(document.getElementById('reg-x').value);
  var y=parseNumberList(document.getElementById('reg-y').value);
  if(x.length<2 || y.length<2 || x.length!==y.length){ errEl.textContent='Isi data X dan Y dengan angka valid, jumlah data X dan Y harus sama (minimal 2 pasang).'; errEl.style.display='block'; document.getElementById('hasil-reg').style.display='none'; return; }
  errEl.style.display='none';
  var res=linearRegression(x,y);
  var tandaB = res.b>=0 ? '+' : '-';
  var persamaan="Y = "+res.a.toPrecision(4)+" "+tandaB+" "+Math.abs(res.b).toPrecision(4)+"X";
  document.getElementById('reg-persamaan').textContent=persamaan;
  document.getElementById('reg-r2').textContent=res.r2.toFixed(4);
  var kualitas = res.r2<0.3 ? "lemah" : (res.r2<0.6 ? "sedang" : (res.r2<0.8 ? "cukup baik" : "sangat baik"));
  document.getElementById('narasi-reg').textContent="Analisis regresi linear sederhana dari "+x.length+" pasang data menghasilkan persamaan "+persamaan+" dengan koefisien determinasi (R2) sebesar "+res.r2.toFixed(4)+", yang berarti sekitar "+(res.r2*100).toFixed(1)+"% variasi Y dapat dijelaskan oleh variabel X. Kekuatan model ini tergolong "+kualitas+".";
  document.getElementById('hasil-reg').style.display='block';
}

/* ===== 69. Scatter Plot ===== */
function buatScatter(){
  var errEl=document.getElementById('err-scatter');
  var x=parseNumberList(document.getElementById('scatter-x').value);
  var y=parseNumberList(document.getElementById('scatter-y').value);
  if(x.length<2 || y.length<2 || x.length!==y.length){ errEl.textContent='Isi data X dan Y dengan angka valid, jumlah data X dan Y harus sama (minimal 2 pasang).'; errEl.style.display='block'; document.getElementById('hasil-scatter').style.display='none'; return; }
  errEl.style.display='none';
  var canvas=document.getElementById('scatter-canvas');
  var ctx=canvas.getContext('2d');
  var W=canvas.width, H=canvas.height;
  clearChart(ctx,W,H);
  var margin={left:55,right:20,top:20,bottom:45};
  var plotW=W-margin.left-margin.right, plotH=H-margin.top-margin.bottom;
  var xMin=Math.min.apply(null,x), xMax=Math.max.apply(null,x);
  var yMin=Math.min.apply(null,y), yMax=Math.max.apply(null,y);
  if(xMin===xMax){ xMin-=1; xMax+=1; }
  if(yMin===yMax){ yMin-=1; yMax+=1; }
  var padX=(xMax-xMin)*0.08, padY=(yMax-yMin)*0.08;
  xMin-=padX; xMax+=padX; yMin-=padY; yMax+=padY;
  function px(v){ return margin.left + ((v-xMin)/(xMax-xMin))*plotW; }
  function py(v){ return margin.top + plotH - ((v-yMin)/(yMax-yMin))*plotH; }
  ctx.strokeStyle="#ccc9c0"; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(margin.left, margin.top); ctx.lineTo(margin.left, margin.top+plotH); ctx.lineTo(margin.left+plotW, margin.top+plotH); ctx.stroke();
  ctx.fillStyle="#5f5e5a"; ctx.font="11px sans-serif"; ctx.textAlign="center";
  ctx.fillText(xMin.toPrecision(3), margin.left, margin.top+plotH+16);
  ctx.fillText(xMax.toPrecision(3), margin.left+plotW, margin.top+plotH+16);
  ctx.save(); ctx.textAlign="right";
  ctx.fillText(yMin.toPrecision(3), margin.left-8, margin.top+plotH+3);
  ctx.fillText(yMax.toPrecision(3), margin.left-8, margin.top+8);
  ctx.restore();
  var reg=linearRegression(x,y);
  ctx.strokeStyle="#a39cf0"; ctx.setLineDash([5,4]); ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(px(xMin), py(reg.a+reg.b*xMin)); ctx.lineTo(px(xMax), py(reg.a+reg.b*xMax)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle="#534ab7";
  for(var i=0;i<x.length;i++){ ctx.beginPath(); ctx.arc(px(x[i]), py(y[i]), 4, 0, Math.PI*2); ctx.fill(); }
  var r=pearsonR(x,y);
  document.getElementById('narasi-scatter').textContent="Scatter plot dari "+x.length+" pasang data X dan Y menunjukkan pola sebaran dengan koefisien korelasi (r) sebesar "+r.toFixed(4)+", tergolong "+classifyR(r)+". Garis putus-putus menunjukkan garis tren regresi linear.";
  document.getElementById('hasil-scatter').style.display='block';
}

/* ===== 70. Histogram ===== */
function buatHistogram(){
  var errEl=document.getElementById('err-histo');
  var data=parseNumberList(document.getElementById('histo-data').value);
  var binsInput=document.getElementById('histo-bins').value;
  if(data.length<3){ errEl.textContent='Masukkan minimal 3 data numerik yang valid.'; errEl.style.display='block'; document.getElementById('hasil-histo').style.display='none'; return; }
  var min=Math.min.apply(null,data), max=Math.max.apply(null,data);
  if(min===max){ errEl.textContent='Semua data bernilai sama, histogram tidak dapat dibuat.'; errEl.style.display='block'; document.getElementById('hasil-histo').style.display='none'; return; }
  errEl.style.display='none';
  var k = parseInt(binsInput);
  if(isNaN(k) || k<1) k = Math.max(1, Math.ceil(Math.log2(data.length)+1));
  var binWidth=(max-min)/k;
  var counts=new Array(k).fill(0);
  data.forEach(function(v){
    var idx=Math.floor((v-min)/binWidth);
    if(idx>=k) idx=k-1;
    if(idx<0) idx=0;
    counts[idx]++;
  });
  var canvas=document.getElementById('histo-canvas');
  var ctx=canvas.getContext('2d');
  var W=canvas.width, H=canvas.height;
  clearChart(ctx,W,H);
  var margin={left:45,right:20,top:20,bottom:55};
  var plotW=W-margin.left-margin.right, plotH=H-margin.top-margin.bottom;
  var maxCount=Math.max.apply(null,counts);
  var barGap=4, barWidth=(plotW/k)-barGap;
  ctx.strokeStyle="#ccc9c0"; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(margin.left, margin.top); ctx.lineTo(margin.left, margin.top+plotH); ctx.lineTo(margin.left+plotW, margin.top+plotH); ctx.stroke();
  ctx.fillStyle="#7f77dd";
  ctx.font="10px sans-serif"; ctx.textAlign="center";
  for(var i=0;i<k;i++){
    var barH = maxCount>0 ? (counts[i]/maxCount)*plotH : 0;
    var bx = margin.left + i*(plotW/k) + barGap/2;
    var by = margin.top+plotH-barH;
    ctx.fillRect(bx, by, barWidth, barH);
    ctx.fillStyle="#5f5e5a";
    ctx.fillText(counts[i], bx+barWidth/2, by-4);
    var labelLow=(min+i*binWidth), labelHigh=(min+(i+1)*binWidth);
    ctx.save(); ctx.translate(bx+barWidth/2, margin.top+plotH+12); ctx.rotate(-Math.PI/6); ctx.textAlign="right";
    ctx.fillText(labelLow.toFixed(1)+"-"+labelHigh.toFixed(1), 0, 0);
    ctx.restore();
    ctx.fillStyle="#7f77dd";
  }
  document.getElementById('narasi-histo').textContent="Histogram dari "+data.length+" data dengan "+k+" kelas (bin) menunjukkan distribusi frekuensi data antara "+min.toPrecision(3)+" sampai "+max.toPrecision(3)+". Kelas dengan frekuensi tertinggi berisi "+maxCount+" data.";
  document.getElementById('hasil-histo').style.display='block';
}

/* ===== 71. Box Plot ===== */
function drawBoxplotCanvas(p){
  if(!p||!p.sorted||!p.sorted.length) return;
  var canvas=document.getElementById('bplot-canvas');
  if(!canvas) return;
  var dpr=window.devicePixelRatio||1;
  var cssW=640, cssH=220;
  canvas.width=cssW*dpr; canvas.height=cssH*dpr;
  canvas.style.width='100%'; canvas.style.maxWidth=cssW+'px'; canvas.style.height='auto';
  var ctx=canvas.getContext('2d');
  ctx.setTransform(dpr,0,0,dpr,0,0);
  var W=cssW, H=cssH;
  var cs=getComputedStyle(document.body);
  function cv(n,f){ return cs.getPropertyValue(n).trim()||f; }
  var textColor=cv('--text-main','#2b221f');
  var secColor=cv('--text-secondary','#5c4740');
  var _accentTmp=cv('--accent-text','');
  var accentColor=_accentTmp||cv('--accent-gold','#e0aa6d');
  var borderColor=cv('--border-subtle','#4b3529');
  var cardBg=cv('--bg-card','#211814');
  var errColor=cv('--error','#c75a4a');
  ctx.clearRect(0,0,W,H);
  var margin={left:50,right:50,top:40,bottom:40};
  var plotW=W-margin.left-margin.right;
  var minVal=Math.min.apply(null,p.sorted), maxVal=Math.max.apply(null,p.sorted);
  var pad=(maxVal-minVal)*0.15||1;
  var scaleMin=minVal-pad, scaleMax=maxVal+pad;
  function px(v){ return margin.left+((v-scaleMin)/(scaleMax-scaleMin))*plotW; }
  var midY=H/2-10, boxHeight=40, axisY=H-margin.bottom;
  ctx.strokeStyle=borderColor; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(margin.left,axisY); ctx.lineTo(W-margin.right,axisY); ctx.stroke();
  ctx.font='12px sans-serif'; ctx.fillStyle=secColor; ctx.textAlign='center';
  for(var t=0;t<=4;t++){
    var val=scaleMin+(t/4)*(scaleMax-scaleMin);
    ctx.beginPath(); ctx.moveTo(px(val),axisY); ctx.lineTo(px(val),axisY+5); ctx.stroke();
    ctx.fillText(val.toFixed(1),px(val),axisY+20);
  }
  ctx.strokeStyle=accentColor; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(px(p.whiskerMin),midY); ctx.lineTo(px(p.q1),midY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(px(p.q3),midY); ctx.lineTo(px(p.whiskerMax),midY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(px(p.whiskerMin),midY-10); ctx.lineTo(px(p.whiskerMin),midY+10); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(px(p.whiskerMax),midY-10); ctx.lineTo(px(p.whiskerMax),midY+10); ctx.stroke();
  var bw=Math.max(1,px(p.q3)-px(p.q1));
  ctx.fillStyle=cardBg; ctx.fillRect(px(p.q1),midY-boxHeight/2,bw,boxHeight);
  ctx.strokeStyle=accentColor; ctx.lineWidth=2; ctx.strokeRect(px(p.q1),midY-boxHeight/2,bw,boxHeight);
  ctx.strokeStyle=textColor; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(px(p.q2),midY-boxHeight/2); ctx.lineTo(px(p.q2),midY+boxHeight/2); ctx.stroke();
  ctx.fillStyle=errColor;
  p.outliers.forEach(function(v){ ctx.beginPath(); ctx.arc(px(v),midY,4,0,Math.PI*2); ctx.fill(); });
  ctx.font='11px sans-serif'; ctx.fillStyle=textColor; ctx.textAlign='center';
  var q1x=px(p.q1), q3x=px(p.q3);
  var qLabelTop=midY-boxHeight/2-8;
  var q3LabelTop=(Math.abs(q3x-q1x)<70)?midY-boxHeight/2-22:midY-boxHeight/2-8;
  ctx.fillText('Q1: '+p.q1.toFixed(1),q1x,qLabelTop);
  ctx.fillText('Q3: '+p.q3.toFixed(1),q3x,q3LabelTop);
  ctx.fillText('Q2: '+p.q2.toFixed(1),px(p.q2),midY+boxHeight/2+14);
  ctx.fillStyle=secColor;
  if(Math.abs(px(p.whiskerMax)-px(p.whiskerMin))<70){
    ctx.textAlign='right';
    ctx.fillText('Min: '+p.whiskerMin.toFixed(1),px(p.whiskerMin)+4,midY+boxHeight/2+32);
    ctx.textAlign='left';
    ctx.fillText('Max: '+p.whiskerMax.toFixed(1),px(p.whiskerMax)-4,midY+boxHeight/2+32);
    ctx.textAlign='center';
  } else {
    ctx.fillText('Min: '+p.whiskerMin.toFixed(1),px(p.whiskerMin),midY+boxHeight/2+32);
    ctx.fillText('Max: '+p.whiskerMax.toFixed(1),px(p.whiskerMax),midY+boxHeight/2+32);
  }
}
(function(){
  var _bplotTimer=null;
  function _bplotRedraw(){ if(window.__bplotLast && document.getElementById('bplot-canvas')) drawBoxplotCanvas(window.__bplotLast); }
  function _bplotDebounce(){ clearTimeout(_bplotTimer); _bplotTimer=setTimeout(_bplotRedraw,50); }
  new MutationObserver(_bplotDebounce).observe(document.body,{attributes:true,attributeFilter:['class','data-soils-theme']});
  new MutationObserver(_bplotDebounce).observe(document.documentElement,{attributes:true,attributeFilter:['class','data-soils-theme']});
  window.addEventListener('resize',_bplotDebounce);
})();
function buatBoxplot(){
  var errEl=document.getElementById('err-bplot');
  var data=parseNumberList(document.getElementById('bplot-data').value);
  if(data.length<4){ errEl.textContent='Masukkan minimal 4 data numerik yang valid.'; errEl.style.display='block'; document.getElementById('hasil-bplot').style.display='none'; return; }
  errEl.style.display='none';
  var sorted=data.slice().sort(function(a,b){return a-b;});
  var q1=percentile(sorted,0.25), q2=percentile(sorted,0.5), q3=percentile(sorted,0.75);
  var iqr=q3-q1;
  var lowerFence=q1-1.5*iqr, upperFence=q3+1.5*iqr;
  var inFence=sorted.filter(function(v){ return v>=lowerFence && v<=upperFence; });
  var whiskerMin=Math.min.apply(null,inFence), whiskerMax=Math.max.apply(null,inFence);
  var outliers=sorted.filter(function(v){ return v<lowerFence || v>upperFence; });
  document.getElementById('bplot-q1').textContent=q1.toPrecision(4);
  document.getElementById('bplot-q2').textContent=q2.toPrecision(4);
  document.getElementById('bplot-q3').textContent=q3.toPrecision(4);
  document.getElementById('bplot-iqr').textContent=iqr.toPrecision(4);
  document.getElementById('bplot-whisker').textContent=whiskerMin.toPrecision(4)+' - '+whiskerMax.toPrecision(4);
  document.getElementById('bplot-outlier').textContent=outliers.length;

  var p={sorted:sorted,q1:q1,q2:q2,q3:q3,whiskerMin:whiskerMin,whiskerMax:whiskerMax,outliers:outliers};
  window.__bplotLast=p;
  drawBoxplotCanvas(p);
  var narasiOutlier = outliers.length>0 ? (" Terdapat "+outliers.length+" data yang terindikasi sebagai outlier (di luar pagar 1,5xIQR).") : " Tidak ditemukan outlier pada data ini.";
  document.getElementById('narasi-bplot').textContent="Box plot dari "+data.length+" data menunjukkan Q1 = "+q1.toPrecision(4)+", median (Q2) = "+q2.toPrecision(4)+", dan Q3 = "+q3.toPrecision(4)+" (IQR = "+iqr.toPrecision(4)+"), dengan whisker dari "+whiskerMin.toPrecision(4)+" hingga "+whiskerMax.toPrecision(4)+"."+narasiOutlier;
  document.getElementById('hasil-bplot').style.display='block';
}

/* ===== 72. Correlation Matrix ===== */
function buatCorrMatrix(){
  var errEl=document.getElementById('err-cormat');
  var raw=document.getElementById('cormat-data').value.trim();
  if(!raw){ errEl.textContent='Masukkan data dengan format: baris pertama nama variabel, baris berikutnya nilai numerik.'; errEl.style.display='block'; document.getElementById('hasil-cormat').style.display='none'; return; }
  var lines=raw.split(/\n+/).map(function(l){return l.trim();}).filter(function(l){return l.length>0;});
  if(lines.length<3){ errEl.textContent='Minimal perlu 1 baris header dan 2 baris data (untuk minimal 3 baris total).'; errEl.style.display='block'; document.getElementById('hasil-cormat').style.display='none'; return; }
  var headers=lines[0].split(',').map(function(h){return h.trim();});
  if(headers.length<2){ errEl.textContent='Minimal perlu 2 kolom variabel, dipisahkan koma pada baris header.'; errEl.style.display='block'; document.getElementById('hasil-cormat').style.display='none'; return; }
  var rows=[];
  for(var i=1;i<lines.length;i++){
    var parts=lines[i].split(',').map(function(p){return parseFloat(p.trim());});
    if(parts.length!==headers.length || parts.some(isNaN)){ errEl.textContent='Baris data ke-'+i+' tidak valid: jumlah kolom harus sama dengan header dan semua nilai harus numerik.'; errEl.style.display='block'; document.getElementById('hasil-cormat').style.display='none'; return; }
    rows.push(parts);
  }
  if(rows.length<3){ errEl.textContent='Minimal perlu 3 baris data numerik untuk menghitung korelasi yang bermakna.'; errEl.style.display='block'; document.getElementById('hasil-cormat').style.display='none'; return; }
  errEl.style.display='none';
  var m=headers.length;
  var columns=[];
  for(var c=0;c<m;c++){ columns.push(rows.map(function(r){return r[c];})); }
  var matrix=[];
  for(var a=0;a<m;a++){
    matrix.push([]);
    for(var b=0;b<m;b++){
      matrix[a].push(a===b ? 1 : pearsonR(columns[a], columns[b]));
    }
  }
  var html='<table class="corr-table"><tr><th></th>';
  headers.forEach(function(h){ html+='<th>'+h+'</th>'; });
  html+='</tr>';
  for(var a=0;a<m;a++){
    html+='<tr><th>'+headers[a]+'</th>';
    for(var b=0;b<m;b++){
      var v=matrix[a][b];
      html+='<td style="background:'+corrColor(v)+'">'+v.toFixed(3)+'</td>';
    }
    html+='</tr>';
  }
  html+='</table>';
  document.getElementById('cormat-table').innerHTML=html;
  var strongest={a:0,b:1,val:0};
  for(var a2=0;a2<m;a2++){ for(var b2=a2+1;b2<m;b2++){ if(Math.abs(matrix[a2][b2])>Math.abs(strongest.val)){ strongest={a:a2,b:b2,val:matrix[a2][b2]}; } } }
  document.getElementById('narasi-cormat').textContent="Correlation matrix dari "+m+" variabel ("+headers.join(', ')+") dengan "+rows.length+" baris data menunjukkan korelasi terkuat antara "+headers[strongest.a]+" dan "+headers[strongest.b]+" dengan r = "+strongest.val.toFixed(4)+" ("+classifyR(strongest.val)+").";
  document.getElementById('hasil-cormat').style.display='block';
}

/* ===== Helper: parsing data kelas interval & frekuensi (untuk Modus & Median Data Kelompok) ===== */
function parseKelasFrekuensi(raw){
  var lines=String(raw||'').split(/\n+/).map(function(l){return l.trim();}).filter(function(l){return l.length>0;});
  var kelas=[];
  for(var i=0;i<lines.length;i++){
    var line=lines[i].replace(/\u00A0/g,' ').replace(/[\u2010-\u2015\u2212]/g,'-').trim();
    /* Ambil koma/semicolon terakhir sebagai pemisah frekuensi.
       Ini membuat format berikut semuanya valid:
       32-26,29 | 32 - 26, 29 | 32–26 , 29 */
    var sep=line.lastIndexOf(',');
    var semi=line.lastIndexOf(';');
    if(semi>sep) sep=semi;
    if(sep<0) return {error:'Baris ke-'+(i+1)+' tidak valid. Format yang benar: batas_bawah-batas_atas, frekuensi'};

    var interval=line.slice(0,sep).trim();
    var freqText=line.slice(sep+1).trim();
    var freq=parseFlexibleNumber(freqText);
    var im=interval.match(/^(-?\d+(?:[.,]\d+)?)\s*-\s*(-?\d+(?:[.,]\d+)?)$/);
    if(!im) return {error:'Interval kelas pada baris ke-'+(i+1)+' tidak valid. Gunakan format seperti 20-24'};
    var low=parseFlexibleNumber(im[1]);
    var up=parseFlexibleNumber(im[2]);
    if(isNaN(low)||isNaN(up)||isNaN(freq)||freq<0) return {error:'Baris ke-'+(i+1)+' mengandung nilai yang tidak valid.'};
    /* User boleh menulis interval terbalik, misalnya 32-26,29.
       Sistem menganggapnya sebagai rentang 26-32 agar tidak gagal hanya
       karena urutan batas interval berbeda. */
    if(up<low){ var tmp=low; low=up; up=tmp; }
    if(up===low) return {error:'Batas bawah dan batas atas tidak boleh sama pada baris ke-'+(i+1)+'.'};
    kelas.push({low:low, up:up, freq:freq});
  }
  if(kelas.length<3) return {error:'Masukkan minimal 3 kelas interval.'};
  for(var j=1;j<kelas.length;j++){
    if(kelas[j].low<=kelas[j-1].low) return {error:'Kelas harus diurutkan menaik berdasarkan batas bawah.'};
  }
  var gap=kelas[1].low-kelas[0].up;
  if(gap<0) return {error:'Kelas-kelas tidak boleh saling tumpang tindih.'};
  var c=kelas[1].low-kelas[0].low;
  for(var k=0;k<kelas.length;k++){
    kelas[k].L0=kelas[k].low-gap/2;
    kelas[k].Lu=kelas[k].up+gap/2;
  }
  return {kelas:kelas, c:c, gap:gap};
}

/* ===== 73. Modus Data Kelompok ===== */
function hitungModusKelompok(){
  var errEl=document.getElementById('err-modus');
  var raw=document.getElementById('modus-data').value.trim();
  if(!raw){ errEl.textContent='Masukkan data kelas interval dan frekuensi.'; errEl.style.display='block'; document.getElementById('hasil-modus').style.display='none'; return; }
  var parsed=parseKelasFrekuensi(raw);
  if(parsed.error){ errEl.textContent=parsed.error; errEl.style.display='block'; document.getElementById('hasil-modus').style.display='none'; return; }
  errEl.style.display='none';
  var kelas=parsed.kelas, c=parsed.c;
  var idxMod=0;
  for(var i=1;i<kelas.length;i++){ if(kelas[i].freq>kelas[idxMod].freq) idxMod=i; }
  var fMod=kelas[idxMod].freq;
  var fSebelum=idxMod>0 ? kelas[idxMod-1].freq : 0;
  var fSesudah=idxMod<kelas.length-1 ? kelas[idxMod+1].freq : 0;
  var b1=fMod-fSebelum, b2=fMod-fSesudah;
  if(b1+b2<=0){ errEl.textContent='Modus tidak dapat dihitung: kelas modus tidak menunjukkan puncak frekuensi yang jelas (b1+b2 <= 0).'; errEl.style.display='block'; document.getElementById('hasil-modus').style.display='none'; return; }
  var L0=kelas[idxMod].L0;
  var Mo=L0+c*(b1/(b1+b2));
  document.getElementById('modus-kelas').textContent=kelas[idxMod].low+' - '+kelas[idxMod].up+' (f = '+fMod+')';
  document.getElementById('modus-l0').textContent=L0.toPrecision(4);
  document.getElementById('modus-c').textContent=c.toPrecision(4);
  document.getElementById('modus-b1').textContent=b1;
  document.getElementById('modus-b2').textContent=b2;
  document.getElementById('modus-hasil').textContent=Mo.toPrecision(5);
  document.getElementById('narasi-modus').textContent="Kelas modus terletak pada interval "+kelas[idxMod].low+"-"+kelas[idxMod].up+" dengan frekuensi tertinggi sebesar "+fMod+". Dengan tepi bawah kelas (L0) = "+L0.toPrecision(4)+", panjang kelas (c) = "+c.toPrecision(4)+", b1 = "+b1+", dan b2 = "+b2+", diperoleh nilai modus (Mo) sebesar "+Mo.toPrecision(5)+".";
  document.getElementById('hasil-modus').style.display='block';
}

/* ===== 74. Median Data Kelompok ===== */
function hitungMedianKelompok(){
  var errEl=document.getElementById('err-median');
  var raw=document.getElementById('median-data').value.trim();
  if(!raw){ errEl.textContent='Masukkan data kelas interval dan frekuensi.'; errEl.style.display='block'; document.getElementById('hasil-median').style.display='none'; return; }
  var parsed=parseKelasFrekuensi(raw);
  if(parsed.error){ errEl.textContent=parsed.error; errEl.style.display='block'; document.getElementById('hasil-median').style.display='none'; return; }
  errEl.style.display='none';
  var kelas=parsed.kelas, c=parsed.c;
  var n=0;
  for(var i=0;i<kelas.length;i++){ n+=kelas[i].freq; }
  var half=n/2;
  var kumulatif=0, idxMed=-1, F=0;
  for(var j=0;j<kelas.length;j++){
    if(kumulatif+kelas[j].freq>=half){ idxMed=j; F=kumulatif; break; }
    kumulatif+=kelas[j].freq;
  }
  if(idxMed===-1){ idxMed=kelas.length-1; F=kumulatif-kelas[idxMed].freq; }
  var f=kelas[idxMed].freq;
  if(f<=0){ errEl.textContent='Median tidak dapat dihitung: frekuensi kelas median bernilai nol.'; errEl.style.display='block'; document.getElementById('hasil-median').style.display='none'; return; }
  var L0=kelas[idxMed].L0;
  var Me=L0+c*((half-F)/f);
  document.getElementById('median-kelas').textContent=kelas[idxMed].low+' - '+kelas[idxMed].up+' (f = '+f+')';
  document.getElementById('median-l0').textContent=L0.toPrecision(4);
  document.getElementById('median-c').textContent=c.toPrecision(4);
  document.getElementById('median-n').textContent=n;
  document.getElementById('median-F').textContent=F;
  document.getElementById('median-f').textContent=f;
  document.getElementById('median-hasil').textContent=Me.toPrecision(5);
  document.getElementById('narasi-median').textContent="Dari total n = "+n+" data, setengah data (n/2) = "+half.toPrecision(4)+" berada pada kelas median interval "+kelas[idxMed].low+"-"+kelas[idxMed].up+" (f = "+f+"). Dengan tepi bawah kelas (L0) = "+L0.toPrecision(4)+", panjang kelas (c) = "+c.toPrecision(4)+", dan frekuensi kumulatif sebelum kelas median (F) = "+F+", diperoleh nilai median (Me) sebesar "+Me.toPrecision(5)+".";
  document.getElementById('hasil-median').style.display='block';
}

/* ===== 75. Rata-Rata Ukur Data Tunggal ===== */
function hitungRataUkurTunggal(){
  var errEl=document.getElementById('err-ukur');
  var data=parseNumberList(document.getElementById('ukur-data').value);
  if(data.length<2){ errEl.textContent='Masukkan minimal 2 data numerik yang valid.'; errEl.style.display='block'; document.getElementById('hasil-ukur').style.display='none'; return; }
  for(var i=0;i<data.length;i++){
    if(data[i]<=0){ errEl.textContent='Rata-rata ukur hanya berlaku untuk data bernilai positif (> 0). Periksa kembali data pada urutan ke-'+(i+1)+'.'; errEl.style.display='block'; document.getElementById('hasil-ukur').style.display='none'; return; }
  }
  errEl.style.display='none';
  var n=data.length;
  var sumLog=0;
  for(var j=0;j<data.length;j++){ sumLog+=Math.log(data[j]); }
  var U=Math.exp(sumLog/n);
  var mean=statMean(data);
  document.getElementById('ukur-n').textContent=n;
  document.getElementById('ukur-hasil').textContent=U.toPrecision(5);
  document.getElementById('ukur-mean').textContent=mean.toPrecision(5);
  document.getElementById('narasi-ukur').textContent="Dari "+n+" data diperoleh rata-rata ukur (U) sebesar "+U.toPrecision(5)+". Sebagai pembanding, rata-rata hitung (mean aritmetik) data ini sebesar "+mean.toPrecision(5)+". Rata-rata ukur selalu lebih kecil atau sama dengan rata-rata hitung, dan lebih tepat digunakan untuk data yang bersifat perbandingan/rasio atau pertumbuhan (misal laju pertumbuhan mikroba, indeks yang bersifat perkalian).";
  document.getElementById('hasil-ukur').style.display='block';
}

/* ===== 76. Rata-Rata Ukur Data Kelompok ===== */
function hitungRataUkurKelompok(){
  var errEl=document.getElementById('err-ukurkel');
  var raw=document.getElementById('ukurkel-data').value.trim();
  if(!raw){ errEl.textContent='Masukkan data kelas interval dan frekuensi.'; errEl.style.display='block'; document.getElementById('hasil-ukurkel').style.display='none'; return; }
  var parsed=parseKelasFrekuensi(raw);
  if(parsed.error){ errEl.textContent=parsed.error; errEl.style.display='block'; document.getElementById('hasil-ukurkel').style.display='none'; return; }
  var kelas=parsed.kelas;
  for(var i=0;i<kelas.length;i++){
    var xi=(kelas[i].low+kelas[i].up)/2;
    if(xi<=0){ errEl.textContent='Rata-rata ukur hanya berlaku jika nilai tengah tiap kelas bernilai positif (> 0). Periksa kembali kelas ke-'+(i+1)+'.'; errEl.style.display='block'; document.getElementById('hasil-ukurkel').style.display='none'; return; }
  }
  errEl.style.display='none';
  var n=0, sumFlog=0;
  for(var j=0;j<kelas.length;j++){
    var xj=(kelas[j].low+kelas[j].up)/2;
    n+=kelas[j].freq;
    sumFlog+=kelas[j].freq*Math.log(xj)/Math.LN10;
  }
  if(n<=0){ errEl.textContent='Jumlah frekuensi (SIGMA fi) harus lebih besar dari nol.'; errEl.style.display='block'; document.getElementById('hasil-ukurkel').style.display='none'; return; }
  var U=Math.pow(10, sumFlog/n);
  document.getElementById('ukurkel-n').textContent=n;
  document.getElementById('ukurkel-sumflog').textContent=sumFlog.toPrecision(5);
  document.getElementById('ukurkel-hasil').textContent=U.toPrecision(5);
  document.getElementById('narasi-ukurkel').textContent="Dari data kelompok dengan total frekuensi (SIGMA fi = n) sebesar "+n+" dan SIGMA(fi . log xi) sebesar "+sumFlog.toPrecision(5)+", diperoleh rata-rata ukur (U) sebesar "+U.toPrecision(5)+" (dihitung sebagai antilog dari SIGMA(fi . log xi) / SIGMA fi menggunakan nilai tengah tiap kelas sebagai xi).";
  document.getElementById('hasil-ukurkel').style.display='block';
}

