/* ===== 92. Konversi Satuan Unsur Hara ke kg/ha ===== */
function convHaraKgha(){
  var errEl=document.getElementById('err-convhara');
  var basis=document.getElementById('convhara-basis').value;
  var kadar=parseFloat(document.getElementById('convhara-kadar').value);
  var bv=parseFloat(document.getElementById('convhara-bv').value);
  var kedalaman=parseFloat(document.getElementById('convhara-kedalaman').value);
  if(isNaN(kadar) || isNaN(bv) || isNaN(kedalaman) || bv<=0 || kedalaman<=0){
    errEl.textContent='Isi semua kolom dengan angka yang valid (BV dan kedalaman harus lebih dari 0).'; errEl.style.display='block';
    document.getElementById('hasil-convhara').style.display='none'; return;
  }
  errEl.style.display='none';
  var bobotTanah = 100000 * kedalaman * bv;
  var hara;
  if(basis==='persen'){ hara = (kadar/100) * bobotTanah; }
  else { hara = (kadar/1000000) * bobotTanah; }
  document.getElementById('convhara-bobot').textContent=formatAngka(bobotTanah)+' kg/ha';
  document.getElementById('convhara-val').textContent=formatAngka(hara)+' kg/ha';
  var basisLabel = basis==='persen' ? '%' : 'ppm';
  document.getElementById('narasi-convhara').textContent="Dengan bobot volume "+bv+" g/cm3 dan kedalaman tanah "+kedalaman+" cm, bobot tanah per hektar adalah "+formatAngka(bobotTanah)+" kg/ha. Kadar unsur "+kadar+" "+basisLabel+" setara dengan kandungan hara sebesar "+formatAngka(hara)+" kg/ha pada lapisan tanah tersebut.";
  document.getElementById('hasil-convhara').style.display='block';
}

/* ===== 93. Kamus Istilah Ilmu Tanah ===== */
var KAMUS_ISTILAH = [
  {t:"Pedon", d:"Satuan volume tanah terkecil yang mewakili suatu tubuh tanah, digunakan sebagai unit dasar pengambilan sampel profil."},
  {t:"Solum", d:"Bagian tanah yang terdiri dari horizon O, A, E, dan B, tempat berlangsungnya proses pembentukan tanah aktif (tidak termasuk horizon C dan R)."},
  {t:"Horizon tanah", d:"Lapisan tanah yang relatif sejajar permukaan dengan ciri morfologi (warna, tekstur, struktur) yang berbeda dari lapisan di atas/bawahnya."},
  {t:"Profil tanah", d:"Penampang vertikal tanah dari permukaan hingga bahan induk, menampilkan seluruh horizon yang ada."},
  {t:"Regolit", d:"Lapisan bahan lepas (hasil pelapukan batuan/sedimen) di atas batuan induk yang belum kompak, mencakup tanah dan bahan induknya."},
  {t:"Bahan induk", d:"Material asal (batuan, sedimen, abu vulkanik) tempat tanah terbentuk melalui proses pelapukan dan pedogenesis."},
  {t:"Eluviasi", d:"Proses pemindahan/kehilangan bahan (liat, besi, humus) dari suatu horizon akibat pencucian air perkolasi."},
  {t:"Iluviasi", d:"Proses pengendapan/akumulasi bahan yang tercuci dari horizon di atasnya pada horizon di bawahnya."},
  {t:"Horizon diagnostik", d:"Horizon dengan ciri kuantitatif tertentu yang digunakan sebagai dasar penetapan klasifikasi tanah (misal horizon argilik, oksik, spodik)."},
  {t:"Epipedon", d:"Horizon diagnostik permukaan yang mencerminkan pengaruh iklim, vegetasi, dan pengelolaan (misal epipedon molik, umbrik, okrik)."},
  {t:"Ordo tanah", d:"Kategori tertinggi dalam sistem klasifikasi USDA Soil Taxonomy, dibedakan berdasarkan proses pembentukan dan horizon diagnostik dominan."},
  {t:"Pedogenesis", d:"Proses pembentukan tanah dari bahan induk melalui pelapukan, penambahan, kehilangan, translokasi, dan transformasi bahan."},
  {t:"Pelapukan (weathering)", d:"Proses penghancuran fisik dan perombakan kimia batuan/mineral menjadi bahan tanah."},
  {t:"KTK (Kapasitas Tukar Kation)", d:"Kemampuan koloid tanah (liat dan humus) menjerap dan menukar kation, dinyatakan dalam me/100g atau cmol(+)/kg."},
  {t:"Kejenuhan Basa (KB)", d:"Persentase KTK yang ditempati oleh kation basa (Ca, Mg, K, Na) dibanding kation asam (Al, H)."},
  {t:"C-organik", d:"Kandungan karbon organik dalam tanah, indikator utama kandungan bahan organik tanah."},
  {t:"Rasio C/N", d:"Perbandingan karbon organik terhadap nitrogen total, indikator tingkat dekomposisi bahan organik."},
  {t:"Mineralisasi", d:"Proses perombakan bahan organik menjadi bentuk mineral (misal N-organik menjadi NH4+/NO3-) oleh mikroba."},
  {t:"Immobilisasi", d:"Proses pengikatan hara mineral (misal N) ke dalam biomassa mikroba, kebalikan dari mineralisasi."},
  {t:"Nitrifikasi", d:"Proses oksidasi biologis amonium (NH4+) menjadi nitrit lalu nitrat (NO3-) oleh bakteri nitrifikasi."},
  {t:"Denitrifikasi", d:"Proses reduksi nitrat menjadi gas nitrogen (N2/N2O) oleh mikroba pada kondisi anaerob, menyebabkan kehilangan N dari tanah."},
  {t:"Fiksasi P", d:"Proses pengikatan fosfat oleh mineral liat/oksida Fe-Al menjadi bentuk yang sukar larut dan tidak tersedia bagi tanaman."},
  {t:"Adsorpsi", d:"Penjerapan ion/molekul pada permukaan koloid tanah."},
  {t:"Pencucian (leaching)", d:"Proses hilangnya hara/basa terlarut dari profil tanah terbawa air perkolasi ke lapisan lebih dalam."},
  {t:"Podsolisasi", d:"Proses pembentukan tanah dengan pencucian intensif sesquioksida dan humus dari horizon eluviasi ke horizon spodik di bawahnya, umum pada iklim dingin/lembab."},
  {t:"Laterisasi", d:"Proses pelapukan lanjut yang mengakumulasi oksida besi dan aluminium (sesquioksida) serta melarutkan silika dan basa, umum di daerah tropis basah."},
  {t:"Salinisasi", d:"Proses akumulasi garam mudah larut dalam tanah hingga menghambat pertumbuhan tanaman."},
  {t:"Sodifikasi", d:"Proses akumulasi natrium tukar (Na+) pada kompleks jerapan tanah hingga merusak struktur tanah."},
  {t:"Gleisasi", d:"Proses reduksi besi akibat kondisi jenuh air/anaerob, menghasilkan warna kelabu kebiruan/kehijauan pada tanah (ciri gley)."},
  {t:"Redoksimorfik", d:"Ciri morfologi (bercak, warna) yang terbentuk akibat proses reduksi-oksidasi besi/mangan periodik dalam tanah jenuh air."},
  {t:"Mottling (bercak karatan)", d:"Bercak warna kontras (biasanya kemerahan/kekuningan) pada matriks tanah yang menandakan drainase terhambat/fluktuasi muka air."},
  {t:"Warna Munsell", d:"Sistem notasi warna tanah standar berdasarkan hue (corak warna), value (kecerahan), dan chroma (kejenuhan warna)."},
  {t:"Tekstur tanah", d:"Perbandingan proporsi fraksi pasir, debu, dan liat dalam tanah, menentukan kelas tekstur menurut segitiga USDA."},
  {t:"Struktur tanah", d:"Susunan agregat (ped) tanah yang terbentuk dari partikel primer yang saling terikat, dicirikan oleh bentuk, ukuran, dan grade."},
  {t:"Konsistensi tanah", d:"Ketahanan tanah terhadap deformasi/hancuran pada berbagai kadar air (kering, lembab, basah)."},
  {t:"Porositas", d:"Persentase volume tanah yang berupa ruang pori (terisi udara dan/atau air) dibanding volume total tanah."},
  {t:"Permeabilitas", d:"Kemampuan tanah meloloskan air atau udara melalui pori-porinya, dinyatakan dalam cm/jam."},
  {t:"Infiltrasi", d:"Proses masuknya air ke dalam tanah melalui permukaan tanah."},
  {t:"Perkolasi", d:"Pergerakan air secara vertikal ke bawah melalui profil tanah menuju lapisan yang lebih dalam."},
  {t:"Kapasitas Lapang", d:"Kadar air tanah maksimum yang dapat ditahan tanah melawan gravitasi setelah kelebihan air mengalir bebas (setara pF 2,54)."},
  {t:"Titik Layu Permanen", d:"Kadar air tanah pada saat tanaman mengalami layu permanen dan tidak dapat pulih meski diberi air (setara pF 4,2)."},
  {t:"Air tersedia", d:"Selisih kadar air antara kapasitas lapang dan titik layu permanen, yaitu air yang dapat dimanfaatkan tanaman."},
  {t:"Bobot Volume (BV)", d:"Massa tanah kering oven per satuan volume tanah utuh (termasuk pori), indikator kepadatan tanah."},
  {t:"Berat Jenis Partikel (BJ)", d:"Massa padatan tanah per satuan volume padatan tanpa pori, umumnya sekitar 2,6-2,7 g/cm3."},
  {t:"Biopori", d:"Lubang/saluran pori tanah yang terbentuk akibat aktivitas akar dan fauna tanah (cacing, serangga)."},
  {t:"Rhizosfer", d:"Zona tanah di sekitar akar tanaman yang dipengaruhi secara langsung oleh aktivitas dan eksudat akar."},
  {t:"Mikoriza", d:"Simbiosis mutualisme antara jamur tanah dan akar tanaman yang membantu penyerapan hara (terutama P) dan air."},
  {t:"Dekomposisi", d:"Proses penguraian bahan organik oleh mikroba dan fauna tanah menjadi senyawa yang lebih sederhana."},
  {t:"Humifikasi", d:"Proses pembentukan humus (bahan organik stabil berwarna gelap) dari hasil dekomposisi bahan organik."},
  {t:"Drainase tanah", d:"Kecepatan dan kelancaran air meresap serta mengalir keluar dari profil tanah."},
  {t:"Erosi tanah", d:"Proses pengikisan dan pengangkutan partikel tanah oleh air, angin, atau gravitasi."}
];
function renderKamus(){
  var q=document.getElementById('kamus-search').value.trim().toLowerCase();
  var filtered = q ? KAMUS_ISTILAH.filter(function(k){ return k.t.toLowerCase().indexOf(q)>=0 || k.d.toLowerCase().indexOf(q)>=0; }) : KAMUS_ISTILAH;
  var el=document.getElementById('kamus-list');
  if(filtered.length===0){ el.innerHTML='<p class="no-result">Istilah tidak ditemukan.</p>'; return; }
  el.innerHTML = filtered.map(function(k){ return '<div class="glossary-item"><p class="term">'+k.t+'</p><p class="def">'+k.d+'</p></div>'; }).join('');
}
renderKamus();

/* ===== 94. Database Parameter Tanah ===== */
