/* ===== Fitur Pencarian Global ===== */
(function(){
  var input = document.getElementById('master-search');
  var clearBtn = document.getElementById('master-search-clear');
  var meta = document.getElementById('master-search-meta');
  var noResult = document.getElementById('master-search-noresult');
  if(!input) return;

  var allNodes = Array.prototype.slice.call(document.querySelectorAll('.group-label, .section'));
  var groups = [];
  var current = null;
  allNodes.forEach(function(node){
    if(node.classList.contains('group-label')){
      current = { label: node, sections: [] };
      groups.push(current);
    } else if(current){
      current.sections.push(node);
    }
  });

  var titleCache = new WeakMap();
  groups.forEach(function(g){
    g.sections.forEach(function(sec){
      var h2 = sec.querySelector('h2');
      if(h2) titleCache.set(h2, h2.textContent);
    });
  });

  var totalSections = groups.reduce(function(n,g){ return n + g.sections.length; }, 0);

  function escapeRegExp(s){ return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
  function normalize(s){ return s.toLowerCase().trim(); }

  function highlight(h2, query){
    var original = titleCache.get(h2);
    if(!original) return;
    if(!query){ h2.textContent = original; return; }
    var re = new RegExp('(' + escapeRegExp(query) + ')', 'ig');
    h2.innerHTML = original.replace(re, '<mark>$1</mark>');
  }

  function runSearch(){
    var q = normalize(input.value);
    clearBtn.style.display = q ? 'block' : 'none';

    if(!q){
      groups.forEach(function(g){
        g.label.classList.remove('ms-hidden');
        g.sections.forEach(function(sec){
          sec.classList.remove('ms-hidden');
          var h2 = sec.querySelector('h2');
          if(h2) highlight(h2, '');
        });
      });
      meta.innerHTML = '';
      noResult.style.display = 'none';
      return;
    }

    var totalMatch = 0;
    groups.forEach(function(g){
      var labelMatches = normalize(g.label.textContent).indexOf(q) >= 0;
      var anyVisible = false;
      g.sections.forEach(function(sec){
        var isMatch = labelMatches || normalize(sec.textContent).indexOf(q) >= 0;
        sec.classList.toggle('ms-hidden', !isMatch);
        var h2 = sec.querySelector('h2');
        if(h2) highlight(h2, isMatch ? q : '');
        if(isMatch){ anyVisible = true; totalMatch++; }
      });
      g.label.classList.toggle('ms-hidden', !anyVisible);
    });

    meta.innerHTML = totalMatch > 0
      ? totalMatch + ' dari ' + totalSections + ' bagian cocok dengan "<mark>' + q.replace(/</g,'&lt;') + '</mark>"'
      : '';
    noResult.style.display = totalMatch === 0 ? 'block' : 'none';
  }

  input.addEventListener('input', runSearch);
  clearBtn.addEventListener('click', function(){
    input.value = '';
    runSearch();
    input.focus();
  });

  document.addEventListener('keydown', function(e){
    if(e.key === '/' && document.activeElement !== input && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA'){
      e.preventDefault();
      input.focus();
    }
  });
})();


/* Extracted from <script> */
/* ===== Global Input Normalizer =====
   Toleransi format input: spasi, dash Unicode, koma desimal, dan
   variasi penulisan data kelompok. Nilai dinormalisasi tepat sebelum
   tombol Hitung menjalankan fungsi kalkulator. */
(function(){
  function normalizeValue(el){
    if(!el || el.disabled) return;
    var tag=(el.tagName||'').toLowerCase();
    if(tag!=='input' && tag!=='textarea') return;
    var raw=String(el.value==null?'':el.value);
    if(!raw.trim()) return;

    var s=raw.replace(/\u00A0/g,' ').trim();
    s=s.replace(/[\u2010-\u2015\u2212]/g,'-');
    s=s.replace(/\s*[-]\s*/g,'-');
    s=s.replace(/\s*[,;]\s*/g,',');

    /* Jangan mengubah koma pada daftar data. Hanya satu angka tunggal
       yang memakai koma sebagai desimal yang dikonversi ke titik. */
    if(/^[+-]?\d+,\d+$/.test(s)) s=s.replace(',', '.');
    else if(/^[+-]?\d{1,3}(?:\.\d{3})+,\d+$/.test(s)) s=s.replace(/\./g,'').replace(',', '.');

    if(s!==raw) el.value=s;
  }

  function normalizeSection(sec){
    if(!sec) return;
    sec.querySelectorAll('input,textarea').forEach(normalizeValue);
  }

  document.addEventListener('click',function(e){
    var btn=e.target.closest ? e.target.closest('button') : null;
    if(!btn) return;
    var sec=btn.closest('.section');
    if(!sec) return;
    var action=(btn.getAttribute('onclick')||'').toLowerCase();
    var text=(btn.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();
    if(action.indexOf('hitung')>=0 || /^hitung\b/.test(text) || text.indexOf('hitung ')===0){
      normalizeSection(sec);
    }
  },true);

  document.addEventListener('blur',function(e){ normalizeValue(e.target); },true);
})();










