(function(window){
  'use strict';
  var VERSION='1.0.0';
  var formulas={};
  var units={
    mass:{mg:0.001,g:1,kg:1000},
    volume:{'mL':1,L:1000},
    length:{mm:1,cm:10,m:1000},
    density:{'g/cm3':1,'kg/m3':0.001}
  };
  function finite(v){return typeof v==='number' && Number.isFinite(v);}
  function num(v){if(typeof v==='number')return v; if(v==null||String(v).trim()==='')return NaN; return Number(String(v).trim().replace(',','.'));}
  function round(v,d){var p=Math.pow(10,d==null?2:d);return Math.round((v+Number.EPSILON)*p)/p;}
  function convert(value,from,to,group){
    if(from===to)return Number(value);
    if(!units[group]||units[group][from]==null||units[group][to]==null)throw new Error('Konversi satuan tidak tersedia: '+from+' → '+to);
    return Number(value)*units[group][from]/units[group][to];
  }
  function validate(spec,raw){
    var errors=[],warnings=[],values={};
    (spec.inputs||[]).forEach(function(i){
      var v=num(raw[i.id]);
      if(raw[i.id]==null||String(raw[i.id]).trim()===''){if(i.required!==false)errors.push(i.label+' wajib diisi.');return;}
      if(!finite(v)){errors.push(i.label+' harus berupa angka yang valid.');return;}
      if(i.min!=null&&v<i.min)errors.push(i.label+' tidak boleh kurang dari '+i.min+'.');
      if(i.max!=null&&v>i.max)errors.push(i.label+' tidak boleh lebih dari '+i.max+'.');
      values[i.id]=v;
    });
    (spec.rules||[]).forEach(function(rule){try{if(rule.when(values)) (rule.level==='warning'?warnings:errors).push(rule.message);}catch(e){}});
    return {ok:errors.length===0,errors:errors,warnings:warnings,values:values};
  }
  function calculate(id,raw,opts){
    var spec=formulas[id];
    if(!spec)throw new Error('Formula tidak terdaftar: '+id);
    var checked=validate(spec,raw);
    if(!checked.ok)return {status:'error',formulaId:id,label:spec.name,errors:checked.errors,warnings:checked.warnings};
    var values=checked.values, value=spec.compute(values), decimals=(opts&&opts.decimals!=null?opts.decimals:(spec.decimals==null?2:spec.decimals));
    if(!finite(value))return {status:'error',formulaId:id,label:spec.name,errors:['Hasil perhitungan tidak valid. Periksa data dan rumus.'],warnings:checked.warnings};
    var result={status:'valid',formulaId:id,label:spec.name,value:value,displayValue:round(value,decimals),unit:spec.output&&spec.output.unit||'',formula:spec.formula||'',substitution:spec.substitute?spec.substitute(values,value):'',warnings:checked.warnings,interpretation:spec.interpret?spec.interpret(value,values):''};
    return result;
  }
  function register(id,spec){if(!id||!spec||typeof spec.compute!=='function')throw new Error('Definisi formula tidak lengkap: '+id);formulas[id]=spec;return spec;}
  function get(id){return formulas[id]||null;}
  window.SOILS_ENGINE={version:VERSION,register:register,get:get,calculate:calculate,validate:function(id,raw){var f=formulas[id];return f?validate(f,raw):{ok:false,errors:['Formula tidak terdaftar: '+id],warnings:[]}},convert:convert,round:round,formulas:formulas};

  register('kadar_air_tanah',{
    name:'Kadar Air Tanah',
    inputs:[
      {id:'berat_basah',label:'Berat tanah basah',unit:'g',required:true,min:0},
      {id:'berat_kering',label:'Berat tanah kering oven',unit:'g',required:true,min:0}
    ],
    formula:'KA (%) = (berat basah − berat kering) / berat kering × 100',
    output:{unit:'%'},decimals:1,
    rules:[{level:'error',when:function(v){return v.berat_kering===0;},message:'Berat tanah kering tidak boleh 0 karena menjadi penyebut.'},{level:'warning',when:function(v){return v.berat_basah<v.berat_kering;},message:'Berat basah lebih kecil daripada berat kering. Periksa kembali data mentah.'}],
    compute:function(v){return ((v.berat_basah-v.berat_kering)/v.berat_kering)*100;},
    substitute:function(v){return '('+v.berat_basah+' − '+v.berat_kering+') / '+v.berat_kering+' × 100';},
    interpret:function(x,v){return 'Berdasarkan berat tanah basah sebesar '+v.berat_basah.toFixed(2)+' g dan berat tanah kering oven sebesar '+v.berat_kering.toFixed(2)+' g, diperoleh kadar air tanah sebesar '+x.toFixed(1)+'%.';}
  });
})(window);


/* Extracted from <script id="raw-data-workspace-js"> */
(function(){
  var STORAGE='SOILS_RAW_DATA_V1';
  var lastResult=null;
  var defs={
    corg:{label:'C-organik — Walkley & Black',fields:[
      ['vk','Volume K2Cr2O7 (mL)','10'],['n','Normalitas FeSO4 / Fe(NH4)2(SO4)2 (N)','0.5'],['s','Volume titrasi blanko, S (mL)','20'],['t','Volume titrasi sampel, T (mL)','12'],['berat','Berat contoh tanah (g)','0.5'],['fk','Faktor koreksi','1.33']]},
    ntotal:{label:'N-total — Kjeldahl',fields:[
      ['s','Volume titrasi blanko, S (mL)','0.3'],['t','Volume titrasi sampel, T (mL)','4.2'],['n','Normalitas HCl (N)','0.05'],['berat','Berat contoh tanah (g)','0.25'],['fp','Faktor pengenceran / aliquot','1']]},
    p:{label:'P-tersedia — Kurva Standar',fields:[
      ['ppm','Konsentrasi terbaca dari kurva standar (ppm)','0.85'],['vekstrak','Volume ekstrak (mL)','50'],['fp','Faktor pengenceran','1'],['berat','Berat contoh tanah (g)','2.5']]},
    basa:{label:'Basa dapat ditukar — AAS/Flamefotometer',fields:[
      ['kation','Jenis kation (Ca/Mg/K/Na)','ca'],['ppm','Konsentrasi terbaca (ppm)','3.2'],['vekstrak','Volume ekstrak (mL)','100'],['fp','Faktor pengenceran','1'],['berat','Berat contoh tanah (g)','5']]},
    ktk:{label:'KTK — NH4OAc',fields:[
      ['s','Volume titrasi blanko, S (mL)','0.2'],['t','Volume titrasi sampel, T (mL)','8.5'],['n','Normalitas titran (N)','0.1'],['berat','Berat contoh tanah (g)','5']]}
  };
  function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function num(id){var el=document.getElementById('raw-'+id);return el?parseFloat(el.value):NaN;}
  function rawRenderFields(){
    var method=document.getElementById('raw-method').value, d=defs[method], el=document.getElementById('raw-fields');
    el.innerHTML='<h3>Input data mentah</h3><div class="raw-grid">'+d.fields.map(function(f){
      if(f[0]==='kation') return '<div><label>'+f[1]+'</label><select id="raw-kation"><option value="ca">Ca (BE 20,04)</option><option value="mg">Mg (BE 12,16)</option><option value="k">K (BE 39,10)</option><option value="na">Na (BE 22,99)</option></select></div>';
      return '<div><label>'+f[1]+'</label><input id="raw-'+f[0]+'" type="number" step="any" placeholder="'+f[2]+'"></div>';
    }).join('')+'</div>';
    if(method==='basa') document.getElementById('raw-kation').value='ca';
    document.getElementById('raw-result').classList.remove('active'); lastResult=null;
  }
  function rawCalculate(){
    var m=document.getElementById('raw-method').value, d=defs[m], sample=(document.getElementById('raw-sample').value||'Tanpa nama').trim(), v={}, errors=[];
    d.fields.forEach(function(f){v[f[0]]=f[0]==='kation'?document.getElementById('raw-kation').value:num(f[0]);});
    if(m==='corg'){
      if([v.vk,v.n,v.s,v.t,v.berat,v.fk].some(isNaN)||v.vk<=0||v.n<=0||v.s<=0||v.t<0||v.berat<=0||v.fk<=0) errors.push('Semua nilai harus valid dan bernilai positif (T boleh 0).');
      if(v.t>=v.s) errors.push('Volume titrasi sampel (T) harus lebih kecil dari blanko (S).');
      if(!errors.length){var rasio=v.t/v.s, val=v.vk*(1-rasio)*v.n*0.003*100/v.berat*v.fk; finish(m,sample,v,val.toFixed(3)+' %','%C-organik = V.K2Cr2O7 × (1 − T/S) × N.FeSO4 × 0,003 × 100 / berat × f.koreksi','Rasio T/S = '+rasio.toFixed(4));}
    } else if(m==='ntotal'){
      if([v.s,v.t,v.n,v.berat,v.fp].some(isNaN)||v.s<0||v.t<0||v.n<=0||v.berat<=0||v.fp<=0) errors.push('Semua nilai harus valid; N, berat, dan fp harus > 0.');
      if(v.t<=v.s) errors.push('Volume titrasi sampel (T) harus lebih besar dari blanko (S).');
      if(!errors.length){var val=((v.t-v.s)*v.n*14.008*v.fp*100)/(v.berat*1000);finish(m,sample,v,val.toFixed(3)+' %','%N-total = (T − S) × N.HCl × 14,008 × fp × 100 / (berat × 1000)','Selisih titrasi = '+(v.t-v.s).toFixed(4)+' mL');}
    } else if(m==='p'){
      if([v.ppm,v.vekstrak,v.fp,v.berat].some(isNaN)||v.ppm<0||v.vekstrak<=0||v.fp<=0||v.berat<=0) errors.push('Konsentrasi boleh 0; volume, fp, dan berat harus > 0.');
      if(!errors.length){var val=v.ppm*v.vekstrak*v.fp/v.berat;finish(m,sample,v,val.toFixed(2)+' ppm','P-tersedia = ppm kurva standar × volume ekstrak × fp / berat contoh','Konsentrasi kurva = '+v.ppm+' ppm');}
    } else if(m==='basa'){
      var be={ca:20.04,mg:12.16,k:39.10,na:22.99}[v.kation];
      if([v.ppm,v.vekstrak,v.fp,v.berat].some(isNaN)||v.ppm<0||v.vekstrak<=0||v.fp<=0||v.berat<=0) errors.push('Konsentrasi boleh 0; volume, fp, dan berat harus > 0.');
      if(!errors.length){var val=(v.ppm*v.vekstrak*v.fp)/(be*v.berat*10);finish(m,sample,v,val.toFixed(3)+' me/100g','Kadar = ppm × volume ekstrak × fp / (BE unsur × berat × 10)','Kation = '+v.kation.toUpperCase()+'; BE = '+be);}
    } else if(m==='ktk'){
      if([v.s,v.t,v.n,v.berat].some(isNaN)||v.s<0||v.t<0||v.n<=0||v.berat<=0) errors.push('Semua nilai harus valid; N dan berat harus > 0.');
      if(v.t<=v.s) errors.push('Volume titrasi sampel (T) harus lebih besar dari blanko (S).');
      if(!errors.length){var val=(v.t-v.s)*v.n*100/v.berat;finish(m,sample,v,val.toFixed(2)+' me/100g','KTK = (T − S) × N.titran × 100 / berat contoh','Selisih titrasi = '+(v.t-v.s).toFixed(4)+' mL');}
    }
    if(errors.length){var r=document.getElementById('raw-result');r.classList.add('active');document.getElementById('raw-result-value').textContent='Data belum valid';document.getElementById('raw-result-detail').innerHTML='<div style="color:#9a4c4c;font-size:12px">'+errors.map(esc).join('<br>')+'</div>';document.getElementById('raw-result-formula').textContent='';document.getElementById('raw-result-status').textContent='Periksa kembali data mentah sebelum disimpan.';lastResult=null;}
  }
  function finish(m,sample,v,result,formula,detail){
    var r=document.getElementById('raw-result');r.classList.add('active');document.getElementById('raw-result-value').textContent=result;document.getElementById('raw-result-detail').textContent=detail;document.getElementById('raw-result-formula').textContent=formula;document.getElementById('raw-result-status').textContent='✓ Data valid • '+defs[m].label+' • sampel: '+sample;
    lastResult={time:new Date().toLocaleString('id-ID'),sample:sample,method:m,label:defs[m].label,values:v,result:result,formula:formula};
  }
  function rawSaveCurrent(){if(!lastResult){rawCalculate();if(!lastResult)return;}var h=[];try{h=JSON.parse(localStorage.getItem(STORAGE)||'[]');}catch(e){}h.unshift(lastResult);h=h.slice(0,100);localStorage.setItem(STORAGE,JSON.stringify(h));rawRenderHistory();document.getElementById('raw-result-status').textContent='✓ Tersimpan ke riwayat lokal.';}
  function rawRenderHistory(){var h=[];try{h=JSON.parse(localStorage.getItem(STORAGE)||'[]');}catch(e){}var body=document.getElementById('raw-history-body');document.getElementById('raw-count').textContent=h.length+' data';if(!h.length){body.innerHTML='<tr><td colspan="5" class="raw-empty">Belum ada data tersimpan.</td></tr>';return;}body.innerHTML=h.map(function(x){return '<tr><td>'+esc(x.time)+'</td><td><strong>'+esc(x.sample)+'</strong></td><td>'+esc(x.label)+'</td><td>'+esc(Object.keys(x.values).map(function(k){return k+': '+x.values[k];}).join(' • '))+'</td><td><strong>'+esc(x.result)+'</strong></td></tr>';}).join('');}
  function rawReset(){document.getElementById('raw-sample').value='';rawRenderFields();}
  function rawClearHistory(){if(!confirm('Hapus seluruh riwayat data mentah?'))return;localStorage.removeItem(STORAGE);rawRenderHistory();}
  function rawExportCSV(){var h=[];try{h=JSON.parse(localStorage.getItem(STORAGE)||'[]');}catch(e){}if(!h.length){alert('Belum ada riwayat untuk diekspor.');return;}var rows=[['Waktu','Sampel','Parameter','Data Mentah','Hasil']];h.forEach(function(x){rows.push([x.time,x.sample,x.label,Object.keys(x.values).map(function(k){return k+'='+x.values[k];}).join(' | '),x.result]);});var csv='\ufeff'+rows.map(function(row){return row.map(function(c){return '"'+String(c).replace(/"/g,'""')+'"';}).join(',');}).join('\n');var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SOILS_RAW_DATA.csv';a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},1000);}
  window.rawRenderFields=rawRenderFields;window.rawCalculate=rawCalculate;window.rawSaveCurrent=rawSaveCurrent;window.rawReset=rawReset;window.rawClearHistory=rawClearHistory;window.rawExportCSV=rawExportCSV;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){rawRenderFields();rawRenderHistory();});else{rawRenderFields();rawRenderHistory();}
})();

