  function setAppearance(mode){var light=mode==='light';document.body.classList.toggle('soils-light-mode',light);document.body.classList.toggle('night-mode',!light);safeSet(APPEARANCE_KEY,light?'light':'dark');updateThemeUI();}
  function updateThemeUI(){var theme=document.body.dataset.soilsTheme||'soil', light=document.body.classList.contains('soils-light-mode');document.querySelectorAll('[data-soils-theme-choice]').forEach(function(b){b.classList.toggle('active',b.dataset.soilsThemeChoice===theme);});document.querySelectorAll('[data-soils-appearance]').forEach(function(b){b.classList.toggle('active',b.dataset.soilsAppearance===(light?'light':'dark'));});}
  function sections(){return [].slice.call(document.querySelectorAll('#soils-calculator-registry .section,#soils-active-form-host .section')).filter(function(s){return s.dataset.soilsTitle||s.querySelector('h2');});}
  function catalogue(){return sections().map(function(s){var h=s.querySelector('h2'), title=(s.dataset.soilsTitle||(h&&h.textContent)||'').replace(/^\s*\d+\.\s*/,'').replace(/\s+/g,' ').trim(), category=s.dataset.soilsCategory||'';return {section:s,title:title,category:category,description:(s.querySelector('p')||{}).textContent||''};});}
  function categoryCards(){var available={};catalogue().forEach(function(x){available[x.category]=true;});return ['Kimia Tanah','Fisika Tanah','Statistik Data','Biologi & Kesuburan','Air & Irigasi','Laboratorium'].filter(function(name){return available[name];});}
  function getHomeContent(){var legacy=document.querySelector('.soils-legacy'), title=legacy&&legacy.querySelector(':scope > h1'), subtitle=legacy&&legacy.querySelector(':scope > .subtitle');return {title:title?title.textContent.trim():'SOILS CALCULATOR PRO',subtitle:subtitle?subtitle.textContent.trim():''};}
